window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[3]={"304":{"example:304:exzh":"He was arrested.","example:304:exzh2":"The reason for the arrest is unclear.","example:304:exzh3":"The police have an arrest warrant.","example:304:exzh4":"She ran away to avoid arrest.","example:304:exzh5":"The arrest was unexpected."},"305":{"example:305:exzh":"He's 20 years old.","example:305:exzh2":"This year I'll turn 31 on my birthday.","example:305:exzh3":"Age is expressed with 「歳」.","example:305:exzh4":"A three-year-old child is playing.","example:305:exzh5":"My little sister turned five this year.","grammar:305:ex:trans":"He is 20 years old.","grammar:305:ex:structure":"noun は + counter + です. 「〜歳」 expresses age and works directly as the predicate.","grammar:305:ex:explain":"「〜歳（さい）」 is the counter for age; it follows a number, so 「20歳」 means 20 years old and can take 「です」 directly as the predicate. 「彼は20歳です」 means he is 20 years old. Note especially that 「20歳」 has the special reading 「はたち」, not 「にじゅっさい」 (though some people say it that way these days) — this exception is a must-remember. Likewise 「一歳＝いっさい」 and 「八歳＝はっさい」 show a doubled-consonant change.","grammar:305:ex:words:0:zh":"he","grammar:305:ex:words:0:note":"かれ","grammar:305:ex:words:0:pos":"pronoun","grammar:305:ex:words:1:zh":"(topic marker)","grammar:305:ex:words:1:pos":"particle","grammar:305:ex:words:2:zh":"20 years old","grammar:305:ex:words:2:note":"hatachi / nijussai；〜歳 expresses age","grammar:305:ex:words:2:pos":"noun","grammar:305:ex:words:3:zh":"is","grammar:305:ex:words:3:pos":"copula","grammar:305:ex:points:0":"〜歳: … years old (20歳 = はたち, a special reading)","grammar:305:ex:points:1":"counter + です: states a numerical value","grammar:305:ex2:trans":"On my birthday this year, I will turn 31.","grammar:305:ex2:structure":"〜で + counter + に + なります. 「〜になる」 expresses change, to become…, and the resulting age takes に.","grammar:305:ex2:words:0:zh":"this year","grammar:305:ex2:words:0:note":"ことし","grammar:305:ex2:words:0:pos":"noun","grammar:305:ex2:words:1:zh":"(topic marker)","grammar:305:ex2:words:1:pos":"particle","grammar:305:ex2:words:2:zh":"I","grammar:305:ex2:words:2:note":"わたし","grammar:305:ex2:words:2:pos":"pronoun","grammar:305:ex2:words:3:zh":"'s","grammar:305:ex2:words:3:pos":"particle","grammar:305:ex2:words:4:zh":"birthday","grammar:305:ex2:words:4:note":"たんじょうび","grammar:305:ex2:words:4:pos":"noun","grammar:305:ex2:words:5:zh":"(time point / cause)","grammar:305:ex2:words:5:pos":"particle","grammar:305:ex2:words:6:zh":"31 years old","grammar:305:ex2:words:6:note":"さんじゅういっさい","grammar:305:ex2:words:6:pos":"noun","grammar:305:ex2:words:7:zh":"(result of the change)","grammar:305:ex2:words:7:pos":"particle","grammar:305:ex2:words:8:zh":"to become","grammar:305:ex2:words:8:note":"なります","grammar:305:ex2:words:8:pos":"verb","grammar:305:ex2:points:0":"〜になる: to become… (に marks the result of the change)","grammar:305:ex2:points:1":"誕生日で: on the birthday (time point)","grammar:305:ex3:trans":"Age is expressed using 「歳」.","grammar:305:ex3:structure":"noun は + noun + で + 表します. 「で」 marks the means: using… (to express).","grammar:305:ex3:words:0:zh":"age","grammar:305:ex3:words:0:note":"ねんれい","grammar:305:ex3:words:0:pos":"noun","grammar:305:ex3:words:1:zh":"(topic marker)","grammar:305:ex3:words:1:pos":"particle","grammar:305:ex3:words:2:zh":"years old","grammar:305:ex3:words:2:note":"さい","grammar:305:ex3:words:2:pos":"noun","grammar:305:ex3:words:3:zh":"use","grammar:305:ex3:words:3:note":"means","grammar:305:ex3:words:3:pos":"particle","grammar:305:ex3:words:4:zh":"express","grammar:305:ex3:words:4:note":"あらわします","grammar:305:ex3:words:4:pos":"verb","grammar:305:ex3:points:0":"で: with / by means of (means / method)","grammar:305:ex3:points:1":"〜で表す: to express using…","grammar:305:ex4:trans":"A three-year-old child is playing.","grammar:305:ex4:structure":"〔counter の noun〕 + が + verb ている. 「3歳の子供」 = a three-year-old child; 〜ている expresses an ongoing action.","grammar:305:ex4:words:0:zh":"three years old","grammar:305:ex4:words:0:note":"さんさい","grammar:305:ex4:words:0:pos":"noun","grammar:305:ex4:words:1:zh":"'s","grammar:305:ex4:words:1:note":"quantity + の + noun","grammar:305:ex4:words:1:pos":"particle","grammar:305:ex4:words:2:zh":"child","grammar:305:ex4:words:2:note":"こども","grammar:305:ex4:words:2:pos":"noun","grammar:305:ex4:words:3:zh":"(nominative)","grammar:305:ex4:words:3:pos":"particle","grammar:305:ex4:words:4:zh":"is playing","grammar:305:ex4:words:4:note":"asoude iru — asonde iru；〜ている expresses an ongoing action","grammar:305:ex4:words:4:pos":"verb","grammar:305:ex4:points:0":"quantity + の + noun: 3歳の子供 (a three-year-old child)","grammar:305:ex4:points:1":"遊ぶ → 遊んで (te-form) + いる","grammar:305:ex5:trans":"My little sister turned five this year.","grammar:305:ex5:structure":"〜は今年〔number〕歳になりました","grammar:305:ex5:words:0:zh":"younger sister","grammar:305:ex5:words:0:note":"いもうと","grammar:305:ex5:words:0:pos":"noun","grammar:305:ex5:words:1:zh":"(topic)","grammar:305:ex5:words:1:pos":"particle","grammar:305:ex5:words:2:zh":"this year","grammar:305:ex5:words:2:note":"ことし","grammar:305:ex5:words:2:pos":"noun","grammar:305:ex5:words:3:zh":"five","grammar:305:ex5:words:3:note":"ご","grammar:305:ex5:words:3:pos":"numeral","grammar:305:ex5:words:4:zh":"years old","grammar:305:ex5:words:4:note":"さい","grammar:305:ex5:words:4:pos":"suffix","grammar:305:ex5:words:5:zh":"(result of the change)","grammar:305:ex5:words:5:pos":"particle","grammar:305:ex5:words:6:zh":"became, reached","grammar:305:ex5:words:6:note":"narimashita；masu-form past","grammar:305:ex5:words:6:pos":"verb","grammar:305:ex5:points:0":"「五歳」: 歳 is read さい and follows a number to express age; here it means five years old.","grammar:305:ex5:points:1":"「〜歳になりました」 uses 「に + なる」 to express reaching a certain age.","grammar:305:ex5:points:2":"「今年」 is read ことし — a common reading that is worth memorizing."},"306":{"example:306:exzh":"Hey, how are you?","grammar:306:ex:trans":"Hey, how are you?","grammar:306:ex:structure":"やあ、〜ですか","grammar:306:ex:explain":"「やあ」 is a light, casual greeting like “hey” or “yo,” used mostly by men and among friends; it sounds friendly and informal and isn't used in formal settings. The following 「元気ですか」 asks “how are you?”; 「元気」 is a na-adjective meaning lively or healthy, and with 「ですか」 it becomes a question. The whole sentence means “Hey, how are you?” A common reply is 「元気です」 (“I'm fine”). A greeting plus a check on how someone is doing is a very everyday combination.","grammar:306:ex:words:0:zh":"hey","grammar:306:ex:words:0:pos":"a set greeting phrase","grammar:306:ex:words:1:zh":"well / healthy","grammar:306:ex:words:1:note":"げんき","grammar:306:ex:words:1:pos":"na-adjective","grammar:306:ex:words:2:zh":"(polite form)","grammar:306:ex:words:2:pos":"copula","grammar:306:ex:words:3:zh":"(question)","grammar:306:ex:words:3:pos":"particle","grammar:306:ex:points:0":"やあ: hey (a casual greeting, often used by men).","grammar:306:ex:points:1":"元気ですか: asking how someone is doing."},"308":{"example:308:exzh":"He's the new president."},"313":{"example:313:exzh":"There's a lot of crime in this area."},"315":{"example:315:exzh":"That's a shame.","grammar:315:ex:trans":"That's too bad.","grammar:315:ex:structure":"〜は残念です","grammar:315:ex:explain":"「残念（ざんねん）」 is a na-adjective meaning “a shame,” “regrettable,” or “disappointing,” used when things don't go as hoped. 「それは残念です」 means “That's too bad.” 「それは」 presents the topic with 「は」, and 「です」 is the polite form. It's a very common way to express regret. Note that 「残念」 takes 「な」 when it modifies a noun (「残念な結果」 = a regrettable result) and attaches directly to 「です」 as a predicate. A related expression is 「残念ながら」.","grammar:315:ex:words:0:zh":"that","grammar:315:ex:words:0:pos":"pronoun","grammar:315:ex:words:1:zh":"(topic)","grammar:315:ex:words:1:pos":"particle","grammar:315:ex:words:2:zh":"regrettable","grammar:315:ex:words:2:note":"ざんねん","grammar:315:ex:words:2:pos":"na-adjective","grammar:315:ex:words:3:zh":"(polite form)","grammar:315:ex:words:3:pos":"copula","grammar:315:ex:points:0":"残念: a shame, regrettable (na-adjective).","grammar:315:ex:points:1":"それは残念です: that's too bad."},"317":{"example:317:exzh":"My name is Tanaka.","example:317:exzh2":"His name is John.","example:317:exzh3":"Please tell me your name.","example:317:exzh4":"Giving something a name is important.","example:317:exzh5":"Her name is Misaki.","grammar:317:ex:trans":"My name is Tanaka.","grammar:317:ex:structure":"〜の名は〜です","grammar:317:ex:explain":"The key word 「名（な）」 means “name” and belongs to literary, written style; in everyday speech people usually say 「名前（なまえ）」. 「私の名は」 uses 「の」 for possession and 「は」 to present the topic, i.e. “my name (is).” 「田中です」 is a noun predicate. The whole sentence means “My name is Tanaka.” 「名」 appears mostly in more formal, literary, or set expressions such as 「名を残す」 (to leave one's name behind); for everyday self-introductions, say 「名前」.","grammar:317:ex:words:0:zh":"I","grammar:317:ex:words:0:note":"わたし","grammar:317:ex:words:0:pos":"pronoun","grammar:317:ex:words:1:zh":"'s","grammar:317:ex:words:1:pos":"particle","grammar:317:ex:words:2:zh":"name","grammar:317:ex:words:2:note":"な","grammar:317:ex:words:2:pos":"noun","grammar:317:ex:words:3:zh":"(topic)","grammar:317:ex:words:3:pos":"particle","grammar:317:ex:words:4:zh":"Tanaka","grammar:317:ex:words:4:note":"たなか","grammar:317:ex:words:4:pos":"noun","grammar:317:ex:words:5:zh":"is","grammar:317:ex:words:5:pos":"copula","grammar:317:ex:points:1":"私の名: my name.","grammar:317:ex2:trans":"His name is John.","grammar:317:ex2:structure":"〜の名は〜です","grammar:317:ex2:words:0:zh":"he","grammar:317:ex2:words:0:note":"かれ","grammar:317:ex2:words:0:pos":"pronoun","grammar:317:ex2:words:1:zh":"'s","grammar:317:ex2:words:1:pos":"particle","grammar:317:ex2:words:2:zh":"name","grammar:317:ex2:words:2:note":"な","grammar:317:ex2:words:2:pos":"noun","grammar:317:ex2:words:3:zh":"(topic)","grammar:317:ex2:words:3:pos":"particle","grammar:317:ex2:words:4:zh":"John","grammar:317:ex2:words:4:note":"a foreign name written in katakana","grammar:317:ex2:words:4:pos":"noun","grammar:317:ex2:words:5:zh":"is","grammar:317:ex2:words:5:pos":"copula","grammar:317:ex2:points:0":"名: name.","grammar:317:ex2:points:1":"彼の名: his name.","grammar:317:ex3:trans":"Please tell me your name.","grammar:317:ex3:structure":"〜を教えてください","grammar:317:ex3:words:0:zh":"you","grammar:317:ex3:words:0:pos":"pronoun","grammar:317:ex3:words:1:zh":"'s","grammar:317:ex3:words:1:pos":"particle","grammar:317:ex3:words:2:zh":"name","grammar:317:ex3:words:2:note":"な","grammar:317:ex3:words:2:pos":"noun","grammar:317:ex3:words:3:zh":"(object marker)","grammar:317:ex3:words:3:pos":"particle","grammar:317:ex3:words:4:zh":"tell","grammar:317:ex3:words:4:note":"おしえて","grammar:317:ex3:words:4:pos":"verb","grammar:317:ex3:words:5:zh":"please","grammar:317:ex3:words:5:pos":"auxiliary verb","grammar:317:ex3:points:0":"名を教える: to tell someone one's name.","grammar:317:ex3:points:1":"教える→教えて＋ください。","grammar:317:ex4:trans":"Giving a name is important.","grammar:317:ex4:structure":"〜のは大切です","grammar:317:ex4:words:0:zh":"name","grammar:317:ex4:words:0:note":"な","grammar:317:ex4:words:0:pos":"noun","grammar:317:ex4:words:1:zh":"(object marker)","grammar:317:ex4:words:1:pos":"particle","grammar:317:ex4:words:2:zh":"give (a name)","grammar:317:ex4:words:2:pos":"verb","grammar:317:ex4:words:3:zh":"(nominalizer)","grammar:317:ex4:words:3:pos":"particle","grammar:317:ex4:words:4:zh":"(topic)","grammar:317:ex4:words:4:pos":"particle","grammar:317:ex4:words:5:zh":"important","grammar:317:ex4:words:5:note":"たいせつ","grammar:317:ex4:words:5:pos":"na-adjective","grammar:317:ex4:words:6:zh":"(polite form)","grammar:317:ex4:words:6:pos":"copula","grammar:317:ex4:points:0":"名をつける: to give a name, to name.","grammar:317:ex4:points:1":"〜のは大切: doing … is important.","grammar:317:ex5:trans":"Her name is Misaki.","grammar:317:ex5:structure":"〜の名は〜です","grammar:317:ex5:words:0:zh":"she","grammar:317:ex5:words:0:note":"かのじょ","grammar:317:ex5:words:0:pos":"pronoun","grammar:317:ex5:words:1:zh":"'s","grammar:317:ex5:words:1:pos":"particle","grammar:317:ex5:words:2:zh":"name","grammar:317:ex5:words:2:note":"な","grammar:317:ex5:words:2:pos":"noun","grammar:317:ex5:words:3:zh":"(topic)","grammar:317:ex5:words:3:pos":"particle","grammar:317:ex5:words:4:zh":"Misaki","grammar:317:ex5:words:4:note":"みさき; a personal name","grammar:317:ex5:words:4:pos":"noun","grammar:317:ex5:words:5:zh":"is","grammar:317:ex5:words:5:pos":"copula","grammar:317:ex5:points:0":"名: name.","grammar:317:ex5:points:1":"彼女の名: her name."},"318":{"example:318:exzh":"That guy is a real jerk.","example:318:exzh2":"What is that bastard thinking?","example:318:exzh3":"He's an especially bad one among those guys.","example:318:exzh4":"I won't forgive that bastard.","example:318:exzh5":"You can become a guy like that."},"319":{"example:319:exzh":"He's hiding a secret.","example:319:exzh2":"You can hide it inside that box.","example:319:exzh3":"Hiding the truth isn't good.","example:319:exzh4":"I hid my own feelings because I was worried.","example:319:exzh5":"She's good at hiding her feelings."},"320":{"example:320:exzh":"He fought bravely.","example:320:exzh2":"They fought more and more fiercely.","example:320:exzh3":"We fight for justice.","example:320:exzh4":"Get ready to fight the enemy.","example:320:exzh5":"She always fights for her own beliefs."},"321":{"example:321:exzh":"Please sit on the chair.","example:321:exzh2":"He's sitting on the floor.","example:321:exzh3":"May I sit here?","example:321:exzh4":"She's sitting on the sofa watching TV.","example:321:exzh5":"We'll sit in front of the desk.","grammar:321:ex:trans":"Please sit on the chair.","grammar:321:ex:structure":"〜に座ってください","grammar:321:ex:explain":"「座る（すわる）」 is an intransitive verb meaning “to sit,” and the place you sit down at (where you land) is marked with 「に」, so 「椅子に座る」 means “sit down on a chair.” Here 「に」 marks the endpoint the action settles on. 「座って」 is the te-form of 「座る」 (る becomes a small っ before て), and with 「ください」 it forms the polite request “please sit.” The whole sentence means “Please sit on the chair.” For sitting down or attaching to a destination, 「に」 is common, as in 「席に着く」.","grammar:321:ex:words:0:zh":"chair","grammar:321:ex:words:0:note":"いす","grammar:321:ex:words:0:pos":"noun","grammar:321:ex:words:1:zh":"(the destination point)","grammar:321:ex:words:1:pos":"particle","grammar:321:ex:words:2:zh":"sit","grammar:321:ex:words:2:note":"すわって","grammar:321:ex:words:2:pos":"verb","grammar:321:ex:words:3:zh":"please","grammar:321:ex:words:3:pos":"auxiliary verb","grammar:321:ex:points:0":"❗座る takes に: you sit onto a place (椅子に座る).","grammar:321:ex:points:1":"座る→座って＋ください。","grammar:321:ex2:trans":"He is sitting on the floor.","grammar:321:ex2:structure":"〜に座っている","grammar:321:ex2:words:0:zh":"he","grammar:321:ex2:words:0:note":"かれ","grammar:321:ex2:words:0:pos":"pronoun","grammar:321:ex2:words:1:zh":"(topic)","grammar:321:ex2:words:1:pos":"particle","grammar:321:ex2:words:2:zh":"floor","grammar:321:ex2:words:2:note":"ゆか","grammar:321:ex2:words:2:pos":"noun","grammar:321:ex2:words:3:zh":"(location of existence)","grammar:321:ex2:words:3:pos":"particle","grammar:321:ex2:words:4:zh":"is sitting","grammar:321:ex2:words:4:note":"すわっている","grammar:321:ex2:words:4:pos":"verb","grammar:321:ex2:points:0":"床に座る: to sit on the floor.","grammar:321:ex2:points:1":"〜ている: the state of (sitting).","grammar:321:ex3:trans":"May I sit here?","grammar:321:ex3:structure":"〜ていいですか","grammar:321:ex3:words:0:zh":"here","grammar:321:ex3:words:0:pos":"pronoun","grammar:321:ex3:words:1:zh":"(the destination point)","grammar:321:ex3:words:1:pos":"particle","grammar:321:ex3:words:2:zh":"sit","grammar:321:ex3:words:2:note":"すわって","grammar:321:ex3:words:2:pos":"verb","grammar:321:ex3:words:3:zh":"it's okay","grammar:321:ex3:words:3:pos":"adjective","grammar:321:ex3:words:4:zh":"(polite form)","grammar:321:ex3:words:4:pos":"copula","grammar:321:ex3:words:5:zh":"(question)","grammar:321:ex3:words:5:pos":"particle","grammar:321:ex3:points:0":"〜ていいですか: may I …? (asking permission, = てもいいですか).","grammar:321:ex3:points:1":"ここに座る: to sit here.","grammar:321:ex4:trans":"She is sitting on the sofa watching TV.","grammar:321:ex4:structure":"〜に座って〜ている","grammar:321:ex4:words:0:zh":"she","grammar:321:ex4:words:0:note":"かのじょ","grammar:321:ex4:words:0:pos":"pronoun","grammar:321:ex4:words:1:zh":"(topic)","grammar:321:ex4:words:1:pos":"particle","grammar:321:ex4:words:2:zh":"sofa","grammar:321:ex4:words:2:note":"loanword","grammar:321:ex4:words:2:pos":"noun","grammar:321:ex4:words:3:zh":"(the destination point)","grammar:321:ex4:words:3:pos":"particle","grammar:321:ex4:words:4:zh":"sit","grammar:321:ex4:words:4:note":"すわって","grammar:321:ex4:words:4:pos":"verb","grammar:321:ex4:words:5:zh":"TV","grammar:321:ex4:words:5:note":"loanword","grammar:321:ex4:words:5:pos":"noun","grammar:321:ex4:words:6:zh":"(object marker)","grammar:321:ex4:words:6:pos":"particle","grammar:321:ex4:words:7:zh":"watching","grammar:321:ex4:words:7:note":"みている","grammar:321:ex4:words:7:pos":"verb","grammar:321:ex4:points:0":"座って: the te-form linking to the next action (sitting and watching).","grammar:321:ex4:points:1":"〜ている: is (watching TV) — an ongoing action.","grammar:321:ex5:trans":"We will sit in front of the desk.","grammar:321:ex5:structure":"〜に座ります","grammar:321:ex5:words:0:zh":"we","grammar:321:ex5:words:0:note":"わたしたち","grammar:321:ex5:words:0:pos":"pronoun","grammar:321:ex5:words:1:zh":"(topic)","grammar:321:ex5:words:1:pos":"particle","grammar:321:ex5:words:2:zh":"desk","grammar:321:ex5:words:2:note":"つくえ","grammar:321:ex5:words:2:pos":"noun","grammar:321:ex5:words:3:zh":"'s","grammar:321:ex5:words:3:pos":"particle","grammar:321:ex5:words:4:zh":"front","grammar:321:ex5:words:4:note":"まえ","grammar:321:ex5:words:4:pos":"noun","grammar:321:ex5:words:5:zh":"(the destination point)","grammar:321:ex5:words:5:pos":"particle","grammar:321:ex5:words:6:zh":"sit","grammar:321:ex5:words:6:note":"すわります","grammar:321:ex5:words:6:pos":"verb","grammar:321:ex5:points:0":"机の前に: in front of the desk.","grammar:321:ex5:points:1":"座る→座ります。","exam:321:zh":"My legs are tired, so I decided to sit on an empty chair.","exam:321:why":"「椅子に座る」 means to sit on a chair and rest. 「立つ」 means to stand, so it can't express sitting down to rest."},"322":{"example:322:exzh":"I live in the country of Japan.","example:322:exzh2":"Which country do you like?","example:322:exzh3":"I heard his country is beautiful.","example:322:exzh4":"This country has a lot of history.","example:322:exzh5":"My country isn't very well known.","grammar:322:ex:trans":"I live in the country of Japan.","grammar:322:ex:structure":"〜に住んでいます","grammar:322:ex:explain":"「住む（すむ）」 means “to live, to reside,” and the place you live is marked with 「に」 (not 「で」), so 「日本の国に住む」 means “live in the country of Japan.” 「住む」 describes a continuing state, so it's customary to use the 「〜ている」 form for “(has been) living”; people rarely say just 「住みます」. 「住んでいます」 is the polite form. The whole sentence means “I live in Japan.” Remember that 「住む」 takes 「に」, not the 「で」 used for where an action happens.","grammar:322:ex:words:0:zh":"I","grammar:322:ex:words:0:note":"わたし","grammar:322:ex:words:0:pos":"pronoun","grammar:322:ex:words:1:zh":"(topic)","grammar:322:ex:words:1:pos":"particle","grammar:322:ex:words:2:zh":"Japan","grammar:322:ex:words:2:note":"にほん","grammar:322:ex:words:2:pos":"noun","grammar:322:ex:words:3:zh":"'s","grammar:322:ex:words:3:pos":"particle","grammar:322:ex:words:4:zh":"country","grammar:322:ex:words:4:note":"くに","grammar:322:ex:words:4:pos":"noun","grammar:322:ex:words:5:zh":"(location of existence)","grammar:322:ex:words:5:pos":"particle","grammar:322:ex:words:6:zh":"live (there)","grammar:322:ex:words:6:note":"すんでいます","grammar:322:ex:words:6:pos":"verb","grammar:322:ex:points:0":"国（くに）: country.","grammar:322:ex:points:1":"〜に住んでいる: to live in ….","grammar:322:ex2:trans":"Which country do you like?","grammar:322:ex2:structure":"どの〜が好きですか","grammar:322:ex2:words:0:zh":"which","grammar:322:ex2:words:0:pos":"pre-noun adjectival","grammar:322:ex2:words:1:zh":"country","grammar:322:ex2:words:1:note":"くに","grammar:322:ex2:words:1:pos":"noun","grammar:322:ex2:words:2:zh":"(object)","grammar:322:ex2:words:2:pos":"particle","grammar:322:ex2:words:3:zh":"to like","grammar:322:ex2:words:3:note":"すき","grammar:322:ex2:words:3:pos":"na-adjective","grammar:322:ex2:words:4:zh":"(polite form)","grammar:322:ex2:words:4:pos":"copula","grammar:322:ex2:words:5:zh":"(question)","grammar:322:ex2:words:5:pos":"particle","grammar:322:ex2:points:0":"どの国: which country (どの＋noun).","grammar:322:ex2:points:1":"The object of 「好き」 takes が.","grammar:322:ex3:trans":"I heard that his country is beautiful.","grammar:322:ex3:structure":"〜と聞きました","grammar:322:ex3:words:0:zh":"he","grammar:322:ex3:words:0:note":"かれ","grammar:322:ex3:words:0:pos":"pronoun","grammar:322:ex3:words:1:zh":"'s","grammar:322:ex3:words:1:pos":"particle","grammar:322:ex3:words:2:zh":"country","grammar:322:ex3:words:2:note":"くに","grammar:322:ex3:words:2:pos":"noun","grammar:322:ex3:words:3:zh":"(topic)","grammar:322:ex3:words:3:pos":"particle","grammar:322:ex3:words:4:zh":"beautiful","grammar:322:ex3:words:4:note":"うつくしい","grammar:322:ex3:words:4:pos":"adjective","grammar:322:ex3:words:5:zh":"(quotation)","grammar:322:ex3:words:5:pos":"particle","grammar:322:ex3:words:6:zh":"heard","grammar:322:ex3:words:6:note":"ききました","grammar:322:ex3:words:6:pos":"verb","grammar:322:ex3:points:0":"〜と聞きました: I heard that … (quotation).","grammar:322:ex3:points:1":"彼の国: his country.","grammar:322:ex4:trans":"This country has a lot of history.","grammar:322:ex4:structure":"〜には〜があります (〜 has 〜)","grammar:322:ex4:words:0:zh":"this","grammar:322:ex4:words:0:pos":"pre-noun adjectival","grammar:322:ex4:words:1:zh":"country","grammar:322:ex4:words:1:note":"くに","grammar:322:ex4:words:1:pos":"noun","grammar:322:ex4:words:2:zh":"(location of existence)","grammar:322:ex4:words:2:pos":"particle","grammar:322:ex4:words:3:zh":"(contrast)","grammar:322:ex4:words:3:pos":"particle","grammar:322:ex4:words:4:zh":"a lot","grammar:322:ex4:words:4:pos":"adverb","grammar:322:ex4:words:5:zh":"'s","grammar:322:ex4:words:5:pos":"particle","grammar:322:ex4:words:6:zh":"history","grammar:322:ex4:words:6:note":"れきし","grammar:322:ex4:words:6:pos":"noun","grammar:322:ex4:words:7:zh":"(nominative)","grammar:322:ex4:words:7:pos":"particle","grammar:322:ex4:words:8:zh":"there is / are","grammar:322:ex4:words:8:pos":"verb","grammar:322:ex4:points:0":"〜には〜がある: … has…, there is… in…","grammar:322:ex4:points:1":"たくさんの歴史: a lot of history.","grammar:322:ex5:trans":"My country isn't very well known.","grammar:322:ex5:structure":"あまり〜ていない","grammar:322:ex5:words:0:zh":"I","grammar:322:ex5:words:0:note":"わたし","grammar:322:ex5:words:0:pos":"pronoun","grammar:322:ex5:words:1:zh":"'s","grammar:322:ex5:words:1:pos":"particle","grammar:322:ex5:words:2:zh":"country","grammar:322:ex5:words:2:note":"くに","grammar:322:ex5:words:2:pos":"noun","grammar:322:ex5:words:3:zh":"(topic)","grammar:322:ex5:words:3:pos":"particle","grammar:322:ex5:words:4:zh":"not very","grammar:322:ex5:words:4:pos":"adverb","grammar:322:ex5:words:5:zh":"not known (by people)","grammar:322:ex5:words:5:note":"しられていない (passive)","grammar:322:ex5:words:5:pos":"verb","grammar:322:ex5:points:0":"❗あまり〜ない: not very …","grammar:322:ex5:points:1":"知られる: to be known (passive); 知られていない: not known (by people).","exam:322:zh":"Japan and China are both countries in Asia.","exam:322:why":"Japan and China are both 「国」. 「町」 means a town and can't refer to a whole country."},"323":{"example:323:exzh":"I'm curious about how the story ends.","example:323:exzh2":"This job ends next month.","example:323:exzh3":"The ending of the movie was touching.","example:323:exzh4":"Our trip came to a happy end.","example:323:exzh5":"The end of this project is important.","grammar:323:ex:trans":"I'm curious about the ending of the story.","grammar:323:ex:structure":"〜が気になる","grammar:323:ex:explain":"The idiom 「気になる」 means “to be on one's mind, to worry about, to be curious about,” and the thing that weighs on you is marked with 「が」, so 「終わりが気になる」 means “I'm curious about the ending.” 「終わり」 is the noun form of the verb 「終わる」, meaning “ending, end.” 「物語の終わり」 uses 「の」 to modify, giving “the ending of the story.” The whole sentence means “I'm curious about how the story ends.” 「気になる」 is an involuntary kind of wondering; it differs in nuance from the deliberate 「気にする」 (to mind something).","grammar:323:ex:words:0:zh":"story","grammar:323:ex:words:0:note":"ものがたり","grammar:323:ex:words:0:pos":"noun","grammar:323:ex:words:1:zh":"'s","grammar:323:ex:words:1:pos":"particle","grammar:323:ex:words:2:zh":"ending","grammar:323:ex:words:2:note":"おわり","grammar:323:ex:words:2:pos":"noun","grammar:323:ex:words:3:zh":"(nominative)","grammar:323:ex:words:3:pos":"particle","grammar:323:ex:words:4:zh":"be on one's mind","grammar:323:ex:words:4:note":"きになる","grammar:323:ex:words:4:pos":"set phrase","grammar:323:ex:points:0":"終わり: ending, end (the noun form of 終わる).","grammar:323:ex:points:1":"気になる: to be on one's mind, to be curious about (idiomatic; the subject takes が).","grammar:323:ex2:trans":"This job ends next month.","grammar:323:ex2:structure":"〜で終わりです","grammar:323:ex2:words:0:zh":"this","grammar:323:ex2:words:0:pos":"pre-noun adjectival","grammar:323:ex2:words:1:zh":"work","grammar:323:ex2:words:1:note":"しごと","grammar:323:ex2:words:1:pos":"noun","grammar:323:ex2:words:2:zh":"(topic)","grammar:323:ex2:words:2:pos":"particle","grammar:323:ex2:words:3:zh":"next month","grammar:323:ex2:words:3:note":"らいげつ","grammar:323:ex2:words:3:pos":"noun","grammar:323:ex2:words:4:zh":"(point in time)","grammar:323:ex2:words:4:pos":"particle","grammar:323:ex2:words:5:zh":"ends","grammar:323:ex2:words:5:note":"おわり","grammar:323:ex2:words:5:pos":"noun","grammar:323:ex2:words:6:zh":"is","grammar:323:ex2:words:6:pos":"copula","grammar:323:ex2:points:0":"〜で終わり: ends at/as of … (a time).","grammar:323:ex2:points:1":"来月で: as of next month.","grammar:323:ex3:trans":"The ending of the movie was moving.","grammar:323:ex3:structure":"〜は〜でした","grammar:323:ex3:words:0:zh":"movie","grammar:323:ex3:words:0:note":"えいが","grammar:323:ex3:words:0:pos":"noun","grammar:323:ex3:words:1:zh":"'s","grammar:323:ex3:words:1:pos":"particle","grammar:323:ex3:words:2:zh":"ending","grammar:323:ex3:words:2:note":"おわり","grammar:323:ex3:words:2:pos":"noun","grammar:323:ex3:words:3:zh":"(topic)","grammar:323:ex3:words:3:pos":"particle","grammar:323:ex3:words:4:zh":"moving","grammar:323:ex3:words:4:note":"かんどうてき","grammar:323:ex3:words:4:pos":"na-adjective","grammar:323:ex3:words:5:zh":"(past) was","grammar:323:ex3:words:5:pos":"copula","grammar:323:ex3:points:0":"感動的: moving, touching (的＋na-adjective).","grammar:323:ex3:points:1":"映画の終わり: the ending of the movie.","grammar:323:ex4:trans":"Our trip came to a happy end.","grammar:323:ex4:structure":"〜を迎えた","grammar:323:ex4:words:0:zh":"we","grammar:323:ex4:words:0:note":"わたしたち","grammar:323:ex4:words:0:pos":"pronoun","grammar:323:ex4:words:1:zh":"'s","grammar:323:ex4:words:1:pos":"particle","grammar:323:ex4:words:2:zh":"travel / trip","grammar:323:ex4:words:2:note":"りょこう","grammar:323:ex4:words:2:pos":"noun","grammar:323:ex4:words:3:zh":"(topic)","grammar:323:ex4:words:3:pos":"particle","grammar:323:ex4:words:4:zh":"fun","grammar:323:ex4:words:4:note":"たのしい","grammar:323:ex4:words:4:pos":"adjective","grammar:323:ex4:words:5:zh":"ends","grammar:323:ex4:words:5:note":"おわり","grammar:323:ex4:words:5:pos":"noun","grammar:323:ex4:words:6:zh":"(object marker)","grammar:323:ex4:words:6:pos":"particle","grammar:323:ex4:words:7:zh":"welcomed","grammar:323:ex4:words:7:note":"むかえた","grammar:323:ex4:words:7:pos":"verb","grammar:323:ex4:points:0":"終わりを迎える: to come to an end, to reach the end (idiomatic expression).","grammar:323:ex4:points:1":"迎える: to welcome.","grammar:323:ex5:trans":"The end of this project is important.","grammar:323:ex5:structure":"〜は重要です","grammar:323:ex5:words:0:zh":"this","grammar:323:ex5:words:0:pos":"pre-noun adjectival","grammar:323:ex5:words:1:zh":"project","grammar:323:ex5:words:1:note":"loanword","grammar:323:ex5:words:1:pos":"noun","grammar:323:ex5:words:2:zh":"'s","grammar:323:ex5:words:2:pos":"particle","grammar:323:ex5:words:3:zh":"ends","grammar:323:ex5:words:3:note":"おわり","grammar:323:ex5:words:3:pos":"noun","grammar:323:ex5:words:4:zh":"(topic)","grammar:323:ex5:words:4:pos":"particle","grammar:323:ex5:words:5:zh":"important","grammar:323:ex5:words:5:note":"じゅうよう","grammar:323:ex5:words:5:pos":"na-adjective","grammar:323:ex5:words:6:zh":"(polite form)","grammar:323:ex5:words:6:pos":"copula","grammar:323:ex5:points:0":"プロジェクトの終わり: the end of the project.","grammar:323:ex5:points:1":"〜は重要です: … is important.","exam:323:zh":"I read this book through to the last page, so I know how the story ends.","exam:323:why":"Reading to the last page tells you the 「終わり」 of the story. 「続き」 means what comes next, not specifically the ending of the story."},"324":{"example:324:exzh":"He's a very strong player.","example:324:exzh2":"The wind is strong, isn't it?","example:324:exzh3":"She has a strong will.","example:324:exzh4":"This tree is strong, so it won't fall.","example:324:exzh5":"We're bound by a strong bond.","grammar:324:ex:trans":"He is a very strong player.","grammar:324:ex:structure":"noun は + とても + i-adjective + noun + です. 「とても」 modifies the adjective, and the adjective modifies the noun.","grammar:324:ex:explain":"This sentence shows two layers of modification: the adverb 「とても」 (very) modifies the adjective, and the adjective 「強い」 then modifies the noun 「選手」. 「とても強い選手」 means a very strong player. An i-adjective attaches directly to a noun with no particle needed. 「彼は…です」 is a noun predicate sentence. The whole sentence means he is a very strong player. An adverb modifying an adjective that in turn modifies a noun is a common stacked-modification structure.","grammar:324:ex:words:0:zh":"he","grammar:324:ex:words:0:note":"かれ","grammar:324:ex:words:0:pos":"pronoun","grammar:324:ex:words:1:zh":"(topic marker)","grammar:324:ex:words:1:pos":"particle","grammar:324:ex:words:2:zh":"extremely","grammar:324:ex:words:2:pos":"adverb","grammar:324:ex:words:3:zh":"strong","grammar:324:ex:words:3:note":"つよい","grammar:324:ex:words:3:pos":"adjective","grammar:324:ex:words:4:zh":"player","grammar:324:ex:words:4:note":"せんしゅ","grammar:324:ex:words:4:pos":"noun","grammar:324:ex:words:5:zh":"is","grammar:324:ex:words:5:pos":"copula","grammar:324:ex:points:0":"とても + adjective: very…","grammar:324:ex:points:1":"i-adjective modifying a noun: 強い選手","grammar:324:ex2:trans":"This wind is strong, isn't it?","grammar:324:ex2:structure":"この + noun + は + i-adjective + ですね. The sentence-final 「ね」 invites the listener's agreement.","grammar:324:ex2:words:0:zh":"this","grammar:324:ex2:words:0:pos":"pre-noun adjectival","grammar:324:ex2:words:1:zh":"wind","grammar:324:ex2:words:1:note":"かぜ","grammar:324:ex2:words:1:pos":"noun","grammar:324:ex2:words:2:zh":"(topic marker)","grammar:324:ex2:words:2:pos":"particle","grammar:324:ex2:words:3:zh":"strong","grammar:324:ex2:words:3:note":"つよい","grammar:324:ex2:words:3:pos":"adjective","grammar:324:ex2:words:4:zh":"(polite form)","grammar:324:ex2:words:4:pos":"copula","grammar:324:ex2:words:5:zh":"right?","grammar:324:ex2:words:5:note":"a tone that seeks agreement","grammar:324:ex2:words:5:pos":"particle","grammar:324:ex2:points:0":"ね: sentence-final, seeking agreement (…, right?)","grammar:324:ex2:points:1":"強いです: i-adjective in polite form","grammar:324:ex3:trans":"She has a strong will.","grammar:324:ex3:structure":"noun は + i-adjective + noun + を + 持っている. 「強い意志を持つ」 = to have a strong will.","grammar:324:ex3:words:0:zh":"she","grammar:324:ex3:words:0:note":"かのじょ","grammar:324:ex3:words:0:pos":"pronoun","grammar:324:ex3:words:1:zh":"(topic marker)","grammar:324:ex3:words:1:pos":"particle","grammar:324:ex3:words:2:zh":"strong","grammar:324:ex3:words:2:note":"つよい","grammar:324:ex3:words:2:pos":"adjective","grammar:324:ex3:words:3:zh":"will","grammar:324:ex3:words:3:note":"いし","grammar:324:ex3:words:3:pos":"noun","grammar:324:ex3:words:4:zh":"(object marker)","grammar:324:ex3:words:4:pos":"particle","grammar:324:ex3:words:5:zh":"own, have","grammar:324:ex3:words:5:note":"motte iru；a state","grammar:324:ex3:words:5:pos":"verb","grammar:324:ex3:points:0":"強い意志: a strong will","grammar:324:ex3:points:1":"〜を持っている: to have… (a state)","grammar:324:ex4:trans":"This tree is strong, so it won't fall.","grammar:324:ex4:structure":"i-adjective + から, verb nai-form. 「から」 expresses cause: because…, so….","grammar:324:ex4:words:0:zh":"this","grammar:324:ex4:words:0:pos":"pre-noun adjectival","grammar:324:ex4:words:1:zh":"tree","grammar:324:ex4:words:1:note":"き","grammar:324:ex4:words:1:pos":"noun","grammar:324:ex4:words:2:zh":"(topic marker)","grammar:324:ex4:words:2:pos":"particle","grammar:324:ex4:words:3:zh":"strong / sturdy","grammar:324:ex4:words:3:note":"つよい","grammar:324:ex4:words:3:pos":"adjective","grammar:324:ex4:words:4:zh":"because","grammar:324:ex4:words:4:note":"expresses cause","grammar:324:ex4:words:4:pos":"particle","grammar:324:ex4:words:5:zh":"won't fall","grammar:324:ex4:words:5:note":"taorenai；nai-form","grammar:324:ex4:words:5:pos":"verb","grammar:324:ex4:points:0":"〜から: because… (cause)","grammar:324:ex4:points:1":"倒れない: the negative form of 倒れる","grammar:324:ex5:trans":"We are bound by a strong bond.","grammar:324:ex5:structure":"noun は + 〜で + 結ばれています. 「結ばれる」 is the passive of 「結ぶ」, and で marks the medium.","grammar:324:ex5:words:0:zh":"we","grammar:324:ex5:words:0:note":"わたしたち","grammar:324:ex5:words:0:pos":"pronoun","grammar:324:ex5:words:1:zh":"(topic marker)","grammar:324:ex5:words:1:pos":"particle","grammar:324:ex5:words:2:zh":"great","grammar:324:ex5:words:2:note":"つよい","grammar:324:ex5:words:2:pos":"adjective","grammar:324:ex5:words:3:zh":"bond","grammar:324:ex5:words:3:note":"きずな","grammar:324:ex5:words:3:pos":"noun","grammar:324:ex5:words:4:zh":"by / with","grammar:324:ex5:words:4:note":"means / medium","grammar:324:ex5:words:4:pos":"particle","grammar:324:ex5:words:5:zh":"are bound together","grammar:324:ex5:words:5:note":"musubarete imasu；passive + ている","grammar:324:ex5:words:5:pos":"verb","grammar:324:ex5:points:0":"結ばれる: to be bound (the passive form of 結ぶ)","grammar:324:ex5:points:1":"で: by means of… (medium / means)","exam:324:zh":"The wind is strong today, so the trees are swaying a lot.","exam:324:why":"Strong wind is 「風が強い」, which also fits the trees swaying hard. 「弱い」 means weak wind, which doesn't match what follows."},"325":{"example:325:exzh":"Which one will you choose?","example:325:exzh2":"Which one do you like best?","example:325:exzh3":"This one or that one—which will you buy?","example:325:exzh4":"They all look delicious, don't they?","example:325:exzh5":"Which one is the correct answer?","grammar:325:ex:trans":"Which one will you choose?","grammar:325:ex:structure":"どれを〜ますか","grammar:325:ex:explain":"The question word 「どれ」 means which one, and it is used to pick from three or more things (use 「どちら」 when choosing between two). In 「どれを」, 「を」 marks the thing being chosen. 「選ぶ」 becomes 「選びます」, the polite form, and adding 「か」 makes it a question. The whole sentence means “Which one will you choose?” Be careful to distinguish 「どれ」 (which one, used on its own) from 「どの」 (which + noun, e.g. どの本): 「どれ」 is never followed by a noun, while 「どの」 always takes one.","grammar:325:ex:words:0:zh":"which one","grammar:325:ex:words:0:pos":"question word","grammar:325:ex:words:1:zh":"(object marker)","grammar:325:ex:words:1:pos":"particle","grammar:325:ex:words:2:zh":"will choose","grammar:325:ex:words:2:note":"えらびますか","grammar:325:ex:words:2:pos":"verb","grammar:325:ex:points:0":"どれ: which one (choosing among three or more).","grammar:325:ex:points:1":"選ぶ→選びます.","grammar:325:ex2:trans":"Which one do you like best?","grammar:325:ex2:structure":"どれが一番好きですか","grammar:325:ex2:words:0:zh":"which one","grammar:325:ex2:words:0:pos":"question word","grammar:325:ex2:words:1:zh":"(object)","grammar:325:ex2:words:1:pos":"particle","grammar:325:ex2:words:2:zh":"the most","grammar:325:ex2:words:2:note":"いちばん","grammar:325:ex2:words:2:pos":"adverb","grammar:325:ex2:words:3:zh":"to like","grammar:325:ex2:words:3:note":"すき","grammar:325:ex2:words:3:pos":"na-adjective","grammar:325:ex2:words:4:zh":"(polite form)","grammar:325:ex2:words:4:pos":"copula","grammar:325:ex2:words:5:zh":"(question)","grammar:325:ex2:words:5:pos":"particle","grammar:325:ex2:points:0":"❓どれが: which one (a question word takes が when it is the subject or the object).","grammar:325:ex2:points:1":"一番好き: to like the most.","grammar:325:ex3:trans":"Which will you buy, this one or that one?","grammar:325:ex3:structure":"どれを〜ますか","grammar:325:ex3:words:0:zh":"this","grammar:325:ex3:words:0:pos":"pronoun","grammar:325:ex3:words:1:zh":"with","grammar:325:ex3:words:1:pos":"particle","grammar:325:ex3:words:2:zh":"that","grammar:325:ex3:words:2:pos":"pronoun","grammar:325:ex3:words:3:zh":"which","grammar:325:ex3:words:3:pos":"question word","grammar:325:ex3:words:4:zh":"(object marker)","grammar:325:ex3:words:4:pos":"particle","grammar:325:ex3:words:5:zh":"will buy","grammar:325:ex3:words:5:note":"かいますか","grammar:325:ex3:words:5:pos":"verb","grammar:325:ex3:points:0":"どれ: which one (among several).","grammar:325:ex3:points:1":"買う→買います.","grammar:325:ex4:trans":"They all look delicious, don't they?","grammar:325:ex4:structure":"どれも〜そうですね","grammar:325:ex4:words:0:zh":"all of them","grammar:325:ex4:words:0:pos":"pronoun","grammar:325:ex4:words:1:zh":"look delicious","grammar:325:ex4:words:1:note":"おいしそう","grammar:325:ex4:words:1:pos":"adjective","grammar:325:ex4:words:2:zh":"(polite form)","grammar:325:ex4:words:2:pos":"copula","grammar:325:ex4:words:3:zh":"right?","grammar:325:ex4:words:3:pos":"particle","grammar:325:ex4:points:0":"❗どれも: all of them, every one (question word + も).","grammar:325:ex4:points:1":"〜そう: looks… (appearance; drop い and add そう).","grammar:325:ex5:trans":"Which one is the correct answer?","grammar:325:ex5:structure":"どれが〜ですか","grammar:325:ex5:words:0:zh":"which one","grammar:325:ex5:words:0:pos":"question word","grammar:325:ex5:words:1:zh":"(nominative)","grammar:325:ex5:words:1:pos":"particle","grammar:325:ex5:words:2:zh":"correct","grammar:325:ex5:words:2:note":"ただしい","grammar:325:ex5:words:2:pos":"adjective","grammar:325:ex5:words:3:zh":"answer","grammar:325:ex5:words:3:note":"こたえ","grammar:325:ex5:words:3:pos":"noun","grammar:325:ex5:words:4:zh":"is","grammar:325:ex5:words:4:pos":"copula","grammar:325:ex5:words:5:zh":"(question)","grammar:325:ex5:words:5:pos":"particle","grammar:325:ex5:points:0":"正しい答え: the correct answer.","grammar:325:ex5:points:1":"どれが〜ですか: which one is…","exam:325:zh":"Which of these three bags is the lightest?","exam:325:why":"To ask which one among several things, you use 「どれ」. 「どこ」 asks about a place, so it can't pick out a particular bag."},"326":{"example:326:exzh":"Hanako is my little sister.","example:326:exzh2":"Between friends, people often add the 「ちゃん」 suffix.","example:326:exzh3":"She calls the dog 「ポチちゃん」.","example:326:exzh4":"Babies are cute too, so it's nice to add 「ちゃん」 to their names when you call them.","example:326:exzh5":"Adding 「ちゃん」 after a name makes it feel more affectionate.","grammar:326:ex:trans":"Hanako is my younger sister.","grammar:326:ex:structure":"〜ちゃんは〜です","grammar:326:ex:explain":"The key point is the suffix 「ちゃん」, which is added after a person's name to show affection. It is used mainly for children, women, or people you are close to, and sounds cuter and more intimate than 「さん」. 「花子ちゃん」 is an affectionate nickname for Hanako. 「〜は〜です」 is a noun sentence pattern, and 「私の妹」 means my younger sister. The whole sentence means “Hanako is my younger sister.” Relatedly, 「くん」 is mainly used for boys or for equals and juniors, while 「さん」 is the general polite honorific; each has a different nuance.","grammar:326:ex:words:0:zh":"Hanako","grammar:326:ex:words:0:note":"はなこ; personal name","grammar:326:ex:words:0:pos":"noun","grammar:326:ex:words:1:zh":"(affectionate honorific)","grammar:326:ex:words:1:pos":"suffix","grammar:326:ex:words:2:zh":"(topic)","grammar:326:ex:words:2:pos":"particle","grammar:326:ex:words:3:zh":"I","grammar:326:ex:words:3:note":"わたし","grammar:326:ex:words:3:pos":"pronoun","grammar:326:ex:words:4:zh":"'s","grammar:326:ex:words:4:pos":"particle","grammar:326:ex:words:5:zh":"younger sister","grammar:326:ex:words:5:note":"いもうと","grammar:326:ex:words:5:pos":"noun","grammar:326:ex:words:6:zh":"is","grammar:326:ex:words:6:pos":"copula","grammar:326:ex:points:0":"❗ちゃん: an affectionate honorific (added after the names of children or people close to you).","grammar:326:ex:points:1":"妹（いもうと）: younger sister.","grammar:326:ex2:trans":"Between friends, people often add 「ちゃん」 to names.","grammar:326:ex2:structure":"〜ことが多い","grammar:326:ex2:words:0:zh":"among friends","grammar:326:ex2:words:0:note":"ともだちどうし","grammar:326:ex2:words:0:pos":"noun","grammar:326:ex2:words:1:zh":"name","grammar:326:ex2:words:1:note":"なまえ","grammar:326:ex2:words:1:pos":"noun","grammar:326:ex2:words:2:zh":"(object)","grammar:326:ex2:words:2:pos":"particle","grammar:326:ex2:words:3:zh":"(honorific)","grammar:326:ex2:words:3:pos":"suffix","grammar:326:ex2:words:4:zh":"(object marker)","grammar:326:ex2:words:4:pos":"particle","grammar:326:ex2:words:5:zh":"add","grammar:326:ex2:words:5:pos":"verb","grammar:326:ex2:words:6:zh":"(nominalizer)","grammar:326:ex2:words:6:pos":"noun","grammar:326:ex2:words:7:zh":"(nominative)","grammar:326:ex2:words:7:pos":"particle","grammar:326:ex2:words:8:zh":"many","grammar:326:ex2:words:8:note":"おおい","grammar:326:ex2:words:8:pos":"adjective","grammar:326:ex2:points:0":"〜同士: between…, with each other.","grammar:326:ex2:points:1":"〜ことが多い: often… (frequency).","grammar:326:ex3:trans":"She calls the dog 「ポチちゃん」.","grammar:326:ex3:structure":"〜を「名前＋ちゃん」と呼んでいる","grammar:326:ex3:explain":"「彼女は」 introduces the topic, and 「犬を」 marks the one being called. 「ポチ」 is the dog's name, and adding 「ちゃん」 gives it an affectionate feel. 「と」 quotes the full name 「ポチちゃん」. The te-form of 「呼ぶ」 is 「呼んで」, and with 「いる」 it forms 「呼んでいる」, which here means that this is how she habitually calls the dog.","grammar:326:ex3:words:0:zh":"she","grammar:326:ex3:words:0:note":"かのじょ","grammar:326:ex3:words:0:pos":"pronoun","grammar:326:ex3:words:1:zh":"(topic)","grammar:326:ex3:words:1:pos":"particle","grammar:326:ex3:words:2:zh":"dog","grammar:326:ex3:words:2:note":"いぬ","grammar:326:ex3:words:2:pos":"noun","grammar:326:ex3:words:3:zh":"(object)","grammar:326:ex3:words:3:pos":"particle","grammar:326:ex3:words:4:zh":"Pochi (the dog's name)","grammar:326:ex3:words:4:pos":"noun","grammar:326:ex3:words:5:zh":"(affectionate address)","grammar:326:ex3:words:5:pos":"suffix","grammar:326:ex3:words:6:zh":"(quotes the name used)","grammar:326:ex3:words:6:pos":"particle","grammar:326:ex3:words:7:zh":"calling; naming","grammar:326:ex3:words:7:note":"よん","grammar:326:ex3:words:7:pos":"verb","grammar:326:ex3:words:8:zh":"(links to a continuing or habitual state)","grammar:326:ex3:words:8:pos":"particle","grammar:326:ex3:words:9:zh":"(ongoing, habitual)","grammar:326:ex3:words:9:pos":"verb","grammar:326:ex3:points:0":"「AをBと呼ぶ」 means to call A B, and 「と」 marks the name being used.","grammar:326:ex3:points:1":"「ちゃん」 follows a name and carries an affectionate, fond tone.","grammar:326:ex3:points:2":"Here 「呼んでいる」 means that this is the name normally used for the dog.","grammar:326:ex4:trans":"Babies are cute too, so it's better to add 「ちゃん」 to the name when you call them.","grammar:326:ex4:structure":"〜から、〜に〜をつけて呼ぶのがいい","grammar:326:ex4:explain":"「赤ちゃん」 is a complete word meaning baby, and 「も」 means too. In 「可愛いから」, 「から」 gives the reason. In 「名前にちゃんをつける」, 「に」 marks what is being added to, and 「を」 marks what is added. 「つけて呼ぶ」 uses the te-form to link the two actions of adding the suffix and calling the name. 「の」 turns the whole preceding action into a noun, and 「がいい」 says that doing so is better or more suitable; this is the speaker's suggestion in this sentence, not a rule that 「ちゃん」 must be used in every situation.","grammar:326:ex4:words:0:zh":"baby","grammar:326:ex4:words:0:note":"あかちゃん","grammar:326:ex4:words:0:pos":"noun","grammar:326:ex4:words:1:zh":"also, too","grammar:326:ex4:words:1:pos":"particle","grammar:326:ex4:words:2:zh":"cute","grammar:326:ex4:words:2:note":"かわいい","grammar:326:ex4:words:2:pos":"i-adjective","grammar:326:ex4:words:3:zh":"(cause)","grammar:326:ex4:words:3:pos":"particle","grammar:326:ex4:words:4:zh":"name","grammar:326:ex4:words:4:note":"なまえ","grammar:326:ex4:words:4:pos":"noun","grammar:326:ex4:words:5:zh":"(what is added to)","grammar:326:ex4:words:5:pos":"particle","grammar:326:ex4:words:6:zh":"(affectionate address)","grammar:326:ex4:words:6:pos":"suffix","grammar:326:ex4:words:7:zh":"(object)","grammar:326:ex4:words:7:pos":"particle","grammar:326:ex4:words:8:zh":"add","grammar:326:ex4:words:8:pos":"verb","grammar:326:ex4:words:9:zh":"(links the two actions)","grammar:326:ex4:words:9:pos":"particle","grammar:326:ex4:words:10:zh":"calling; naming","grammar:326:ex4:words:10:note":"よぶ","grammar:326:ex4:words:10:pos":"verb","grammar:326:ex4:words:11:zh":"(nominalizes the action)","grammar:326:ex4:words:11:pos":"particle","grammar:326:ex4:words:12:zh":"(nominative)","grammar:326:ex4:words:12:pos":"particle","grammar:326:ex4:words:13:zh":"good, suitable","grammar:326:ex4:words:13:pos":"i-adjective","grammar:326:ex4:points:0":"「AにBをつける」 means to add B to A.","grammar:326:ex4:points:1":"「verb dictionary form ＋ のがいい」 means that doing something is good or advisable.","grammar:326:ex4:points:2":"「ちゃん」 has an affectionate tone, so consider the relationship and the situation when using it.","grammar:326:ex5:trans":"Adding 「ちゃん」 after a name brings a greater sense of closeness.","grammar:326:ex5:structure":"〜と、〜が増す","grammar:326:ex5:words:0:zh":"name","grammar:326:ex5:words:0:note":"なまえ","grammar:326:ex5:words:0:pos":"noun","grammar:326:ex5:words:1:zh":"'s","grammar:326:ex5:words:1:pos":"particle","grammar:326:ex5:words:2:zh":"later, afterwards","grammar:326:ex5:words:2:note":"あと","grammar:326:ex5:words:2:pos":"noun","grammar:326:ex5:words:3:zh":"(point in time)","grammar:326:ex5:words:3:pos":"particle","grammar:326:ex5:words:4:zh":"(honorific)","grammar:326:ex5:words:4:pos":"suffix","grammar:326:ex5:words:5:zh":"(object marker)","grammar:326:ex5:words:5:pos":"particle","grammar:326:ex5:words:6:zh":"add","grammar:326:ex5:words:6:pos":"verb","grammar:326:ex5:words:7:zh":"(condition)","grammar:326:ex5:words:7:pos":"particle","grammar:326:ex5:words:8:zh":"sense of closeness","grammar:326:ex5:words:8:note":"したしみ","grammar:326:ex5:words:8:pos":"noun","grammar:326:ex5:words:9:zh":"(nominative)","grammar:326:ex5:words:9:pos":"particle","grammar:326:ex5:words:10:zh":"increase","grammar:326:ex5:words:10:note":"ます","grammar:326:ex5:words:10:pos":"verb","grammar:326:ex5:points:0":"〜と: as soon as…, then… (natural result).","grammar:326:ex5:points:1":"親しみが増す: closeness increases."},"327":{"example:327:exzh":"Let's talk about that matter later.","example:327:exzh2":"I have something important to discuss, so please listen.","example:327:exzh3":"I need to sort out a few matters.","example:327:exzh4":"That's a good matter.","example:327:exzh5":"Please think about this matter carefully."},"329":{"example:329:exzh":"I'm sure he'll come.","example:329:exzh2":"That book must be interesting.","example:329:exzh3":"It'll definitely clear up.","example:329:exzh4":"She's sure to be happy.","example:329:exzh5":"We can definitely succeed.","grammar:329:ex:trans":"I think he will definitely come.","grammar:329:ex:structure":"きっと〜と思います","grammar:329:ex:explain":"The adverb 「きっと」 expresses a strong guess or conviction — definitely, surely — and often pairs with expressions of conjecture. 「〜と思います」 means I think that…, I believe that…; 「と」 is the quotation particle marking what is thought, and 「思う」 means to think. 「彼はきっと来る」 is the content of the thought, so the whole sentence 「彼はきっと来ると思います」 means “I think he will definitely come.” 「きっと」 sounds more certain than 「たぶん」 (probably).","grammar:329:ex:words:0:zh":"he","grammar:329:ex:words:0:note":"かれ","grammar:329:ex:words:0:pos":"pronoun","grammar:329:ex:words:1:zh":"(topic)","grammar:329:ex:words:1:pos":"particle","grammar:329:ex:words:2:zh":"definitely","grammar:329:ex:words:2:pos":"adverb","grammar:329:ex:words:3:zh":"come","grammar:329:ex:words:3:note":"くる","grammar:329:ex:words:3:pos":"verb","grammar:329:ex:words:4:zh":"(quotation)","grammar:329:ex:words:4:pos":"particle","grammar:329:ex:words:5:zh":"to think about","grammar:329:ex:words:5:note":"おもいます","grammar:329:ex:words:5:pos":"verb","grammar:329:ex:points:0":"きっと: definitely, surely (strong conjecture).","grammar:329:ex:points:1":"〜と思います: I think that…","grammar:329:ex2:trans":"That book will surely be interesting.","grammar:329:ex2:structure":"きっと〜でしょう","grammar:329:ex2:words:0:zh":"that","grammar:329:ex2:words:0:pos":"pre-noun adjectival","grammar:329:ex2:words:1:zh":"book","grammar:329:ex2:words:1:note":"ほん","grammar:329:ex2:words:1:pos":"noun","grammar:329:ex2:words:2:zh":"(topic)","grammar:329:ex2:words:2:pos":"particle","grammar:329:ex2:words:3:zh":"definitely","grammar:329:ex2:words:3:pos":"adverb","grammar:329:ex2:words:4:zh":"interesting","grammar:329:ex2:words:4:note":"おもしろい","grammar:329:ex2:words:4:pos":"adjective","grammar:329:ex2:words:5:zh":"probably","grammar:329:ex2:words:5:pos":"auxiliary verb","grammar:329:ex2:points:0":"きっと〜でしょう: will surely…, I'm sure…","grammar:329:ex2:points:1":"面白い: interesting, fun.","grammar:329:ex3:trans":"It will definitely clear up.","grammar:329:ex3:structure":"きっと〜よ","grammar:329:ex3:words:0:zh":"definitely","grammar:329:ex3:words:0:pos":"adverb","grammar:329:ex3:words:1:zh":"to clear up","grammar:329:ex3:words:1:note":"はれる","grammar:329:ex3:words:1:pos":"verb","grammar:329:ex3:words:2:zh":"(informing)","grammar:329:ex3:words:2:pos":"particle","grammar:329:ex3:points:0":"きっと: definitely.","grammar:329:ex3:points:1":"晴れる: to clear up; よ: a particle that informs or assures the listener.","grammar:329:ex4:trans":"She will definitely be happy.","grammar:329:ex4:structure":"きっと〜はずです","grammar:329:ex4:words:0:zh":"definitely","grammar:329:ex4:words:0:pos":"adverb","grammar:329:ex4:words:1:zh":"she","grammar:329:ex4:words:1:note":"かのじょ","grammar:329:ex4:words:1:pos":"pronoun","grammar:329:ex4:words:2:zh":"(topic)","grammar:329:ex4:words:2:pos":"particle","grammar:329:ex4:words:3:zh":"be happy","grammar:329:ex4:words:3:note":"よろこぶ","grammar:329:ex4:words:3:pos":"verb","grammar:329:ex4:words:4:zh":"should","grammar:329:ex4:words:4:pos":"auxiliary verb","grammar:329:ex4:words:5:zh":"(polite form)","grammar:329:ex4:words:5:pos":"copula","grammar:329:ex4:points:0":"❗〜はずです: should… (a guess based on evidence).","grammar:329:ex4:points:1":"きっと＋はず: reinforces certainty.","grammar:329:ex5:trans":"We will definitely succeed.","grammar:329:ex5:structure":"〜ことはきっとできます","grammar:329:ex5:words:0:zh":"success","grammar:329:ex5:words:0:note":"せいこうする","grammar:329:ex5:words:0:pos":"verb","grammar:329:ex5:words:1:zh":"(nominalizer)","grammar:329:ex5:words:1:pos":"noun","grammar:329:ex5:words:2:zh":"(topic)","grammar:329:ex5:words:2:pos":"particle","grammar:329:ex5:words:3:zh":"definitely","grammar:329:ex5:words:3:pos":"adverb","grammar:329:ex5:words:4:zh":"be able to","grammar:329:ex5:words:4:pos":"verb","grammar:329:ex5:points:0":"〜ことができる: to be able to…","grammar:329:ex5:points:1":"きっと: definitely."},"330":{"example:330:exzh":"I'm definitely going to go.","example:330:exzh2":"This is absolutely correct.","example:330:exzh3":"You can say it will absolutely not fail.","example:330:exzh4":"He's someone you can absolutely trust.","example:330:exzh5":"I believe we'll definitely win."},"331":{"example:331:exzh":"Police officers have blocked the road.","example:331:exzh2":"He's an experienced police officer.","example:331:exzh3":"I asked a police officer for help.","example:331:exzh4":"Police officers work to prevent crime.","example:331:exzh5":"Local police officers keep the area safe."},"332":{"example:332:exzh":"He lost blood.","example:332:exzh2":"Bleeding hurts.","example:332:exzh3":"What's your blood type?","example:332:exzh4":"Human blood is red.","example:332:exzh5":"A blood test will tell you the result.","grammar:332:ex:trans":"He lost blood.","grammar:332:ex:structure":"〜を失った","grammar:332:ex:explain":"「血（ち）」 means blood. 「失う（うしなう）」 is a transitive verb meaning to lose; here the object is 「血」, so 「血を失う」 means to lose blood. 「失った」 is the plain past form (う changes to っ, giving 失った). The whole sentence means “He lost blood.” 「失う」 has a heavier, more written tone and can be used for concrete things (blood, belongings) or abstract ones (confidence, consciousness); for casually losing small things in everyday speech, 「なくす」 is more common.","grammar:332:ex:words:0:zh":"he","grammar:332:ex:words:0:note":"かれ","grammar:332:ex:words:0:pos":"pronoun","grammar:332:ex:words:1:zh":"(topic)","grammar:332:ex:words:1:pos":"particle","grammar:332:ex:words:2:zh":"blood","grammar:332:ex:words:2:note":"ち","grammar:332:ex:words:2:pos":"noun","grammar:332:ex:words:3:zh":"(object marker)","grammar:332:ex:words:3:pos":"particle","grammar:332:ex:words:4:zh":"lost","grammar:332:ex:words:4:note":"うしなった","grammar:332:ex:words:4:pos":"verb","grammar:332:ex:points:0":"血（ち）: blood.","grammar:332:ex:points:1":"失う: to lose; 失う→失った.","grammar:332:ex2:trans":"Bleeding is painful.","grammar:332:ex2:structure":"〜のは痛い","grammar:332:ex2:words:0:zh":"blood","grammar:332:ex2:words:0:note":"ち","grammar:332:ex2:words:0:pos":"noun","grammar:332:ex2:words:1:zh":"(nominative)","grammar:332:ex2:words:1:pos":"particle","grammar:332:ex2:words:2:zh":"flow","grammar:332:ex2:words:2:note":"ながれる","grammar:332:ex2:words:2:pos":"verb","grammar:332:ex2:words:3:zh":"(nominalizer)","grammar:332:ex2:words:3:pos":"particle","grammar:332:ex2:words:4:zh":"(topic)","grammar:332:ex2:words:4:pos":"particle","grammar:332:ex2:words:5:zh":"hurt / painful","grammar:332:ex2:words:5:note":"いたい","grammar:332:ex2:words:5:pos":"adjective","grammar:332:ex2:points:0":"血が流れる: blood flows, to bleed (intransitive verb; the subject takes が).","grammar:332:ex2:points:1":"〜のは: the fact of…, the act of …ing.","grammar:332:ex3:trans":"What is your blood type?","grammar:332:ex3:structure":"〜は何ですか","grammar:332:ex3:words:0:zh":"blood type","grammar:332:ex3:words:0:note":"けつえきがた","grammar:332:ex3:words:0:pos":"noun","grammar:332:ex3:words:1:zh":"(topic)","grammar:332:ex3:words:1:pos":"particle","grammar:332:ex3:words:2:zh":"what","grammar:332:ex3:words:2:note":"なに","grammar:332:ex3:words:2:pos":"question word","grammar:332:ex3:words:3:zh":"is","grammar:332:ex3:words:3:pos":"copula","grammar:332:ex3:words:4:zh":"(question)","grammar:332:ex3:words:4:pos":"particle","grammar:332:ex3:points:0":"❗血液（けつえき）: blood (on-yomi); 血液型 = blood type.","grammar:332:ex3:points:1":"何ですか: asks what something is.","grammar:332:ex4:trans":"Human blood is red.","grammar:332:ex4:structure":"〜は赤い","grammar:332:ex4:words:0:zh":"humans","grammar:332:ex4:words:0:note":"にんげん","grammar:332:ex4:words:0:pos":"noun","grammar:332:ex4:words:1:zh":"'s","grammar:332:ex4:words:1:pos":"particle","grammar:332:ex4:words:2:zh":"blood","grammar:332:ex4:words:2:note":"ち","grammar:332:ex4:words:2:pos":"noun","grammar:332:ex4:words:3:zh":"(topic)","grammar:332:ex4:words:3:pos":"particle","grammar:332:ex4:words:4:zh":"red","grammar:332:ex4:words:4:note":"あかい","grammar:332:ex4:words:4:pos":"adjective","grammar:332:ex4:points:0":"人間の血: human blood.","grammar:332:ex4:points:1":"「赤い」: red (i-adjective).","grammar:332:ex5:trans":"The results can be found out with a blood test.","grammar:332:ex5:structure":"〜で〜がわかる","grammar:332:ex5:words:0:zh":"blood test","grammar:332:ex5:words:0:note":"けつえきけんさ","grammar:332:ex5:words:0:pos":"noun","grammar:332:ex5:words:1:zh":"(means)","grammar:332:ex5:words:1:pos":"particle","grammar:332:ex5:words:2:zh":"result","grammar:332:ex5:words:2:note":"けっか","grammar:332:ex5:words:2:pos":"noun","grammar:332:ex5:words:3:zh":"(nominative)","grammar:332:ex5:words:3:pos":"particle","grammar:332:ex5:words:4:zh":"know","grammar:332:ex5:words:4:pos":"verb","grammar:332:ex5:points:0":"❓で: by means of… (means).","grammar:332:ex5:points:1":"〜がわかる: to find out, to understand (with わかる, the object takes が)."},"334":{"example:334:exzh":"He's a fan of detective dramas.","example:334:exzh2":"A detective's job is to solve cases.","example:334:exzh3":"The detective is doing a stakeout.","example:334:exzh4":"His dad is a detective.","example:334:exzh5":"Criminal cases are always interesting."},"335":{"example:335:exzh":"My teacher is very kind.","example:335:exzh2":"Teacher, thanks for your hard work.","example:335:exzh3":"There are two teachers in this classroom.","example:335:exzh4":"The teacher is checking the homework.","example:335:exzh5":"The children respect their teacher.","grammar:335:ex:trans":"My teacher is very kind.","grammar:335:ex:structure":"〜は〜","grammar:335:ex:explain":"The key word 「先生（せんせい）」 does not only mean teacher; it is also used to respectfully address professionals such as doctors, lawyers, politicians, and writers. 「私の先生は」 uses 「は」 to introduce the topic, and 「優しい」 is an i-adjective meaning kind, gentle; here it is in the plain form, with no です at the end. The whole sentence means “My teacher is very kind.” Calling someone 「先生」 is an honorific, but you would not say 「私は先生です」 about yourself to elevate your own status; be mindful of the situation.","grammar:335:ex:words:0:zh":"I","grammar:335:ex:words:0:note":"わたし","grammar:335:ex:words:0:pos":"pronoun","grammar:335:ex:words:1:zh":"'s","grammar:335:ex:words:1:pos":"particle","grammar:335:ex:words:2:zh":"teacher","grammar:335:ex:words:2:note":"せんせい","grammar:335:ex:words:2:pos":"noun","grammar:335:ex:words:3:zh":"(topic)","grammar:335:ex:words:3:pos":"particle","grammar:335:ex:words:4:zh":"extremely","grammar:335:ex:words:4:pos":"adverb","grammar:335:ex:words:5:zh":"gentle","grammar:335:ex:words:5:note":"やさしい","grammar:335:ex:words:5:pos":"adjective","grammar:335:ex:points:0":"先生（せんせい）: teacher (also used for doctors, lawyers, etc.).","grammar:335:ex:points:1":"優しい: kind, gentle.","grammar:335:ex2:trans":"Thank you for your hard work, teacher.","grammar:335:ex2:structure":"先生、〜","grammar:335:ex2:words:0:zh":"teacher","grammar:335:ex2:words:0:note":"せんせい","grammar:335:ex2:words:0:pos":"noun","grammar:335:ex2:words:1:zh":"thanks for your hard work","grammar:335:ex2:words:1:note":"おつかれさまです","grammar:335:ex2:words:1:pos":"set phrase","grammar:335:ex2:points:0":"お疲れ様です: thank you for your hard work (a phrase of appreciation).","grammar:335:ex2:points:1":"先生: a way to address a teacher.","grammar:335:ex3:trans":"There are two teachers in this classroom.","grammar:335:ex3:structure":"〜には〜がいます","grammar:335:ex3:words:0:zh":"this","grammar:335:ex3:words:0:pos":"pre-noun adjectival","grammar:335:ex3:words:1:zh":"classroom","grammar:335:ex3:words:1:note":"きょうしつ","grammar:335:ex3:words:1:pos":"noun","grammar:335:ex3:words:2:zh":"(location of existence)","grammar:335:ex3:words:2:pos":"particle","grammar:335:ex3:words:3:zh":"(contrast)","grammar:335:ex3:words:3:pos":"particle","grammar:335:ex3:words:4:zh":"two people","grammar:335:ex3:words:4:note":"ふたり","grammar:335:ex3:words:4:pos":"noun","grammar:335:ex3:words:5:zh":"'s","grammar:335:ex3:words:5:pos":"particle","grammar:335:ex3:words:6:zh":"teacher","grammar:335:ex3:words:6:note":"せんせい","grammar:335:ex3:words:6:pos":"noun","grammar:335:ex3:words:7:zh":"(nominative)","grammar:335:ex3:words:7:pos":"particle","grammar:335:ex3:words:8:zh":"there is / are","grammar:335:ex3:words:8:pos":"verb","grammar:335:ex3:points:0":"二人の先生: two teachers.","grammar:335:ex3:points:1":"に＋がいます: there is (a person) in a place.","grammar:335:ex4:trans":"The teacher is checking the homework.","grammar:335:ex4:structure":"〜をチェックしています","grammar:335:ex4:words:0:zh":"teacher","grammar:335:ex4:words:0:note":"せんせい","grammar:335:ex4:words:0:pos":"noun","grammar:335:ex4:words:1:zh":"(topic)","grammar:335:ex4:words:1:pos":"particle","grammar:335:ex4:words:2:zh":"homework","grammar:335:ex4:words:2:note":"しゅくだい","grammar:335:ex4:words:2:pos":"noun","grammar:335:ex4:words:3:zh":"(object marker)","grammar:335:ex4:words:3:pos":"particle","grammar:335:ex4:words:4:zh":"is checking","grammar:335:ex4:words:4:pos":"verb","grammar:335:ex4:points:0":"チェックする: to check (loanword + する).","grammar:335:ex4:points:1":"〜ている: ongoing action.","grammar:335:ex5:trans":"The children respect the teacher.","grammar:335:ex5:structure":"〜を尊敬しています","grammar:335:ex5:words:0:zh":"children","grammar:335:ex5:words:0:note":"こどもたち","grammar:335:ex5:words:0:pos":"noun","grammar:335:ex5:words:1:zh":"(topic)","grammar:335:ex5:words:1:pos":"particle","grammar:335:ex5:words:2:zh":"teacher","grammar:335:ex5:words:2:note":"せんせい","grammar:335:ex5:words:2:pos":"noun","grammar:335:ex5:words:3:zh":"(object marker)","grammar:335:ex5:words:3:pos":"particle","grammar:335:ex5:words:4:zh":"respects","grammar:335:ex5:words:4:note":"そんけいしています","grammar:335:ex5:words:4:pos":"verb","grammar:335:ex5:points:0":"尊敬する: to respect.","grammar:335:ex5:points:1":"〜ている: an ongoing feeling.","exam:335:zh":"Tanaka-san is the teacher who teaches math to students at this school every day.","exam:335:why":"Someone whose job is teaching students at a school is a 「先生」. 「学生」 means a person who studies, which doesn't match the teaching job described here."},"337":{"example:337:exzh":"He's a member of the team.","example:337:exzh2":"I work as a member of the company.","example:337:exzh3":"The organization's members gathered.","example:337:exzh4":"She's a member of the club.","example:337:exzh5":"Many members took part."},"339":{"example:339:exzh":"Do you understand what I'm saying?","example:339:exzh2":"I understand the guidelines.","example:339:exzh3":"I understand my boss's instructions.","example:339:exzh4":"He understands that situation.","example:339:exzh5":"Understood, thank you."},"340":{"example:340:exzh":"There's enough time.","example:340:exzh2":"His explanation was thorough.","example:340:exzh3":"This meal is enough.","example:340:exzh4":"The preparation is sufficient.","example:340:exzh5":"Please get plenty of rest.","grammar:340:ex:trans":"There is plenty of time.","grammar:340:ex:structure":"noun は + 十分 + あります. 「十分」 works as an adverb modifying 「ある」, meaning (time) exists in plenty.","grammar:340:ex:explain":"The key is 「十分（じゅうぶん）」, used here as an adverb meaning fully, sufficiently, modifying the verb 「ある」; 「十分あります」 means there is more than enough time. 「時間は」 uses 「は」 to present the topic. The whole sentence means there is plenty of time. Note that 「十分」 read 「じゅうぶん」 means sufficient, while read 「じっぷん／じゅっぷん」 it means ten minutes — same characters, different reading, completely different meaning.","grammar:340:ex:words:0:zh":"time","grammar:340:ex:words:0:note":"じかん","grammar:340:ex:words:0:pos":"noun","grammar:340:ex:words:1:zh":"(topic marker)","grammar:340:ex:words:1:pos":"particle","grammar:340:ex:words:2:zh":"sufficiently","grammar:340:ex:words:2:note":"jūbun；here it works as an adverb modifying the verb","grammar:340:ex:words:2:pos":"adverb","grammar:340:ex:words:3:zh":"there is / are","grammar:340:ex:words:3:note":"exists / there is","grammar:340:ex:words:3:pos":"verb","grammar:340:ex:points:0":"十分: can work as the adverb sufficiently","grammar:340:ex:points:1":"時間が十分ある: there is enough time","grammar:340:ex2:trans":"His explanation was sufficient.","grammar:340:ex2:structure":"〔noun の noun〕 + は + na-adjective + でした. 「十分」 works as a na-adjective predicate, with でした for the past.","grammar:340:ex2:words:0:zh":"he","grammar:340:ex2:words:0:note":"かれ","grammar:340:ex2:words:0:pos":"pronoun","grammar:340:ex2:words:1:zh":"'s","grammar:340:ex2:words:1:pos":"particle","grammar:340:ex2:words:2:zh":"explain","grammar:340:ex2:words:2:note":"せつめい","grammar:340:ex2:words:2:pos":"noun","grammar:340:ex2:words:3:zh":"(topic marker)","grammar:340:ex2:words:3:pos":"particle","grammar:340:ex2:words:4:zh":"plenty","grammar:340:ex2:words:4:note":"jūbun；here it works as a na-adjective predicate","grammar:340:ex2:words:4:pos":"na-adjective","grammar:340:ex2:words:5:zh":"(polite past)","grammar:340:ex2:words:5:pos":"copula","grammar:340:ex2:points:0":"十分: can also work as the na-adjective sufficient","grammar:340:ex2:points:1":"でした: the past of です (polite past)","grammar:340:ex3:trans":"This meal is enough.","grammar:340:ex3:structure":"この + noun + は + na-adjective + です. 「十分です」 = is enough.","grammar:340:ex3:words:0:zh":"this","grammar:340:ex3:words:0:pos":"pre-noun adjectival","grammar:340:ex3:words:1:zh":"meal / food","grammar:340:ex3:words:1:note":"しょくじ","grammar:340:ex3:words:1:pos":"noun","grammar:340:ex3:words:2:zh":"(topic marker)","grammar:340:ex3:words:2:pos":"particle","grammar:340:ex3:words:3:zh":"enough","grammar:340:ex3:words:3:note":"じゅうぶん","grammar:340:ex3:words:3:pos":"na-adjective","grammar:340:ex3:words:4:zh":"(polite form)","grammar:340:ex3:words:4:pos":"copula","grammar:340:ex3:points:0":"十分です: that's enough","grammar:340:ex3:points:1":"na-adjective predicate + です","grammar:340:ex4:trans":"The preparations are sufficient.","grammar:340:ex4:structure":"noun は + na-adjective + です. 「準備は十分です」 = the preparations are sufficient.","grammar:340:ex4:words:0:zh":"prepare","grammar:340:ex4:words:0:note":"じゅんび","grammar:340:ex4:words:0:pos":"noun","grammar:340:ex4:words:1:zh":"(topic marker)","grammar:340:ex4:words:1:pos":"particle","grammar:340:ex4:words:2:zh":"enough","grammar:340:ex4:words:2:note":"じゅうぶん","grammar:340:ex4:words:2:pos":"na-adjective","grammar:340:ex4:words:3:zh":"(polite form)","grammar:340:ex4:words:3:pos":"copula","grammar:340:ex4:points:0":"十分です: sufficient","grammar:340:ex4:points:1":"〜は…です: describes a state","grammar:340:ex5:trans":"Please get plenty of rest.","grammar:340:ex5:structure":"〔na-adjective + に〕 + verb てください. 「十分に」 uses に to become an adverb modifying the verb.","grammar:340:ex5:words:0:zh":"sufficiently","grammar:340:ex5:words:0:note":"jūbun ni；na-adjective + に to form an adverb","grammar:340:ex5:words:0:pos":"adverb","grammar:340:ex5:words:1:zh":"please rest","grammar:340:ex5:words:1:note":"yasunde kudasai；te-form + ください","grammar:340:ex5:words:1:pos":"verb","grammar:340:ex5:points:0":"na-adjective + に = adverb: 十分に (fully)","grammar:340:ex5:points:1":"〜てください: please do…"},"342":{"example:342:exzh":"She changed her hairstyle.","example:342:exzh2":"I have to change the way I think.","example:342:exzh3":"I want to change this plan too.","example:342:exzh4":"I want to change the world.","example:342:exzh5":"Let's change that approach.","grammar:342:ex:trans":"She changed her hairstyle.","grammar:342:ex:structure":"〜を変えました","grammar:342:ex:explain":"「変える（かえる）」 is a transitive verb meaning to change or alter; the thing being changed takes 「を」, so 「髪型を変える」 means to change one's hairstyle. It pairs with the intransitive 「変わる」 (to change by itself): use 「変える」 when a person actively changes something and 「変わる」 when something changes on its own — this pair is easy to mix up. 「変えました」 is the polite past. The whole sentence means she changed her hairstyle. To decide which to use, ask whether someone is actively changing something.","grammar:342:ex:words:0:zh":"she","grammar:342:ex:words:0:note":"かのじょ","grammar:342:ex:words:0:pos":"pronoun","grammar:342:ex:words:1:zh":"(topic)","grammar:342:ex:words:1:pos":"particle","grammar:342:ex:words:2:zh":"hairstyle","grammar:342:ex:words:2:note":"かみがた","grammar:342:ex:words:2:pos":"noun","grammar:342:ex:words:3:zh":"(object marker)","grammar:342:ex:words:3:pos":"particle","grammar:342:ex:words:4:zh":"changed","grammar:342:ex:words:4:note":"かえました","grammar:342:ex:words:4:pos":"verb","grammar:342:ex:points:0":"❗「変える（かえる）」: to change, to alter (transitive verb); vs. 「変わる」 (intransitive, to change); 「髪型を変える」 = to change one's hairstyle.","grammar:342:ex:points:1":"「髪型を変える」: to change one's hairstyle.","grammar:342:ex2:trans":"You have to change the way you think.","grammar:342:ex2:structure":"〜を変えなければなりません","grammar:342:ex2:words:0:zh":"way of thinking","grammar:342:ex2:words:0:note":"かんがえかた","grammar:342:ex2:words:0:pos":"noun","grammar:342:ex2:words:1:zh":"(object marker)","grammar:342:ex2:words:1:pos":"particle","grammar:342:ex2:words:2:zh":"must change","grammar:342:ex2:words:2:note":"かえなければなりません","grammar:342:ex2:words:2:pos":"verb","grammar:342:ex2:points:0":"❗「考え方を変える」: to change one's way of thinking; 〜なければなりません = must …","grammar:342:ex2:points:1":"「考え方を変える」: to change one's way of thinking.","grammar:342:ex3:trans":"I want to change this plan too.","grammar:342:ex3:structure":"〜を変えたいです","grammar:342:ex3:words:0:zh":"I","grammar:342:ex3:words:0:note":"わたし","grammar:342:ex3:words:0:pos":"pronoun","grammar:342:ex3:words:1:zh":"also, too","grammar:342:ex3:words:1:pos":"particle","grammar:342:ex3:words:2:zh":"this","grammar:342:ex3:words:2:pos":"pre-noun adjectival","grammar:342:ex3:words:3:zh":"plan","grammar:342:ex3:words:3:note":"けいかく","grammar:342:ex3:words:3:pos":"noun","grammar:342:ex3:words:4:zh":"(object marker)","grammar:342:ex3:words:4:pos":"particle","grammar:342:ex3:words:5:zh":"want to change","grammar:342:ex3:words:5:note":"かえたい","grammar:342:ex3:words:5:pos":"verb","grammar:342:ex3:words:6:zh":"(polite form)","grammar:342:ex3:words:6:pos":"copula","grammar:342:ex3:points:0":"❗「計画を変える」: to change a plan; 〜たい = want to …","grammar:342:ex3:points:1":"「計画を変える」: to change a plan.","grammar:342:ex4:trans":"I want to change the world.","grammar:342:ex4:structure":"〜を変えたいと思います","grammar:342:ex4:words:0:zh":"world","grammar:342:ex4:words:0:note":"せかい","grammar:342:ex4:words:0:pos":"noun","grammar:342:ex4:words:1:zh":"(object marker)","grammar:342:ex4:words:1:pos":"particle","grammar:342:ex4:words:2:zh":"want to change","grammar:342:ex4:words:2:note":"かえたい","grammar:342:ex4:words:2:pos":"verb","grammar:342:ex4:words:3:zh":"(quotation)","grammar:342:ex4:words:3:pos":"particle","grammar:342:ex4:words:4:zh":"think","grammar:342:ex4:words:4:note":"おもいます","grammar:342:ex4:words:4:pos":"verb","grammar:342:ex4:points:0":"❗「世界を変える」: to change the world; 〜たいと思う = to want to …","grammar:342:ex4:points:1":"「世界を変える」: to change the world.","grammar:342:ex5:trans":"Let's change that approach.","grammar:342:ex5:structure":"〜を変えましょう","grammar:342:ex5:words:0:zh":"that","grammar:342:ex5:words:0:pos":"pre-noun adjectival","grammar:342:ex5:words:1:zh":"way, method","grammar:342:ex5:words:1:note":"ほうほう","grammar:342:ex5:words:1:pos":"noun","grammar:342:ex5:words:2:zh":"(object marker)","grammar:342:ex5:words:2:pos":"particle","grammar:342:ex5:words:3:zh":"let's change","grammar:342:ex5:words:3:note":"かえましょう","grammar:342:ex5:words:3:pos":"verb","grammar:342:ex5:points:0":"❗「方法を変える」: to change the method; 〜ましょう = let's …","grammar:342:ex5:points:1":"「方法を変える」: to change the method."},"343":{"example:343:exzh":"Is he doing well?","example:343:exzh2":"I think he's doing well.","example:343:exzh3":"Please stay well.","example:343:exzh4":"We're doing well.","example:343:exzh5":"Energetic children.","grammar:343:ex:trans":"Is he doing all right?","grammar:343:ex:structure":"〜は元気ですか","grammar:343:ex:explain":"「元気（げんき）」 is a na-adjective meaning energetic, healthy, full of life. 「元気ですか」 is the most common greeting: “How are you? Are you well?” 「彼は」 uses 「は」 to introduce the topic, and 「ですか」 is the polite question form. The whole sentence means “Is he doing all right?” A reply can be 「元気です」 (I'm fine). Note that 「元気」 takes 「です」 directly as a predicate, and only adds 「な」 when it modifies a noun (元気な子 = an energetic child).","grammar:343:ex:words:0:zh":"he","grammar:343:ex:words:0:note":"かれ","grammar:343:ex:words:0:pos":"pronoun","grammar:343:ex:words:1:zh":"(topic)","grammar:343:ex:words:1:pos":"particle","grammar:343:ex:words:2:zh":"well / healthy","grammar:343:ex:words:2:note":"げんき","grammar:343:ex:words:2:pos":"na-adjective","grammar:343:ex:words:3:zh":"(polite form)","grammar:343:ex:words:3:pos":"copula","grammar:343:ex:words:4:zh":"(question)","grammar:343:ex:words:4:pos":"particle","grammar:343:ex:points:0":"元気: energetic, healthy (na-adjective).","grammar:343:ex:points:1":"元気ですか: asking how someone is doing.","grammar:343:ex2:trans":"I think he is doing well.","grammar:343:ex2:structure":"〜と思います","grammar:343:ex2:words:0:zh":"in good health","grammar:343:ex2:words:0:note":"げんきに","grammar:343:ex2:words:0:pos":"adverb","grammar:343:ex2:words:1:zh":"(living)","grammar:343:ex2:words:1:pos":"verb","grammar:343:ex2:words:2:zh":"(quotation)","grammar:343:ex2:words:2:pos":"particle","grammar:343:ex2:words:3:zh":"to think about","grammar:343:ex2:words:3:note":"おもいます","grammar:343:ex2:words:3:pos":"verb","grammar:343:ex2:points:0":"元気にしている: doing well, getting along fine (na-adjective + に + している).","grammar:343:ex2:points:1":"〜と思います: I think that…","grammar:343:ex3:trans":"Please stay healthy.","grammar:343:ex3:structure":"〜でいてください","grammar:343:ex3:words:0:zh":"well / healthy","grammar:343:ex3:words:0:note":"げんき","grammar:343:ex3:words:0:pos":"na-adjective","grammar:343:ex3:words:1:zh":"(te-form)","grammar:343:ex3:words:1:pos":"auxiliary verb","grammar:343:ex3:words:2:zh":"stay","grammar:343:ex3:words:2:pos":"verb","grammar:343:ex3:words:3:zh":"please","grammar:343:ex3:words:3:pos":"auxiliary verb","grammar:343:ex3:points:0":"〜でいてください: please stay… (in that state).","grammar:343:ex3:points:1":"元気でいる: to stay healthy.","grammar:343:ex4:trans":"We are healthy.","grammar:343:ex4:structure":"〜は元気です","grammar:343:ex4:words:0:zh":"we","grammar:343:ex4:words:0:note":"わたしたち","grammar:343:ex4:words:0:pos":"pronoun","grammar:343:ex4:words:1:zh":"(topic)","grammar:343:ex4:words:1:pos":"particle","grammar:343:ex4:words:2:zh":"well / healthy","grammar:343:ex4:words:2:note":"げんき","grammar:343:ex4:words:2:pos":"na-adjective","grammar:343:ex4:words:3:zh":"(polite form)","grammar:343:ex4:words:3:pos":"copula","grammar:343:ex4:points:0":"元気です: (we) are well.","grammar:343:ex4:points:1":"「私たち」: we.","grammar:343:ex5:trans":"Healthy children.","grammar:343:ex5:structure":"元気な〜","grammar:343:ex5:words:0:zh":"well / healthy","grammar:343:ex5:words:0:note":"げんき","grammar:343:ex5:words:0:pos":"na-adjective","grammar:343:ex5:words:1:zh":"(attributive form)","grammar:343:ex5:words:1:pos":"auxiliary verb","grammar:343:ex5:words:2:zh":"children","grammar:343:ex5:words:2:note":"こどもたち","grammar:343:ex5:words:2:pos":"noun","grammar:343:ex5:points:0":"元気な子供たち: energetic children (na-adjective + noun).","grammar:343:ex5:points:1":"子供たち: children.","exam:343:zh":"My illness got better, I'm well again, and I can play outside once more.","exam:343:why":"「元気になる」 means to get well or recover your energy. 「暇になる」 means to become free, which can't express getting your strength back after an illness."},"344":{"example:344:exzh":"I like him best.","example:344:exzh2":"This is the most important thing.","example:344:exzh3":"Got up the earliest.","example:344:exzh4":"What do you like best?","example:344:exzh5":"The place I want to go most.","grammar:344:ex:trans":"I like him best.","grammar:344:ex:structure":"noun + が + 一番 + 好きです. 「一番」 expresses the superlative, most….","grammar:344:ex:explain":"The key is 「一番（いちばん）」, used as an adverb for the superlative most…, so 「一番好き」 means like best. In 「彼が一番好きです」, the object of liking takes 「が」 (the rule for objects of liking), and the whole sentence means I like him best. 「一番」 originally means number one and extends to most; it is the most common way to express the superlative in Japanese, as in 「一番高い（the most expensive）」 and 「一番いい（the best）」.","grammar:344:ex:words:0:zh":"he","grammar:344:ex:words:0:note":"かれ","grammar:344:ex:words:0:pos":"pronoun","grammar:344:ex:words:1:zh":"(object marker)","grammar:344:ex:words:1:note":"the object of 好き","grammar:344:ex:words:1:pos":"particle","grammar:344:ex:words:2:zh":"the most","grammar:344:ex:words:2:note":"ichiban；superlative","grammar:344:ex:words:2:pos":"adverb","grammar:344:ex:words:3:zh":"to like","grammar:344:ex:words:3:note":"すき","grammar:344:ex:words:3:pos":"na-adjective","grammar:344:ex:words:4:zh":"(polite form)","grammar:344:ex:words:4:pos":"copula","grammar:344:ex:points:0":"一番: the most… (superlative adverb)","grammar:344:ex:points:1":"〜が一番好き: like … best","grammar:344:ex2:trans":"This is the most important.","grammar:344:ex2:structure":"これ + が + 一番 + na-adjective + です. 「が」 emphasizes this is the one, and 一番 marks the superlative.","grammar:344:ex2:words:0:zh":"this","grammar:344:ex2:words:0:pos":"pronoun","grammar:344:ex2:words:1:zh":"(nominative)","grammar:344:ex2:words:1:note":"emphasizes the subject","grammar:344:ex2:words:1:pos":"particle","grammar:344:ex2:words:2:zh":"the most","grammar:344:ex2:words:2:note":"いちばん","grammar:344:ex2:words:2:pos":"adverb","grammar:344:ex2:words:3:zh":"important","grammar:344:ex2:words:3:note":"だいじ","grammar:344:ex2:words:3:pos":"na-adjective","grammar:344:ex2:words:4:zh":"(polite form)","grammar:344:ex2:words:4:pos":"copula","grammar:344:ex2:points:0":"これが一番…: this is the most… (が marks emphasis)","grammar:344:ex2:points:1":"一番大事: the most important","grammar:344:ex3:trans":"Got up the earliest.","grammar:344:ex3:structure":"一番 + 〔i-adjective continuative〕 + verb ました. 「一番早く」 = the earliest.","grammar:344:ex3:words:0:zh":"the most","grammar:344:ex3:words:0:note":"いちばん","grammar:344:ex3:words:0:pos":"adverb","grammar:344:ex3:words:1:zh":"early (as an adverb)","grammar:344:ex3:words:1:note":"hayaku；the continuative form used as an adverb","grammar:344:ex3:words:1:pos":"adjective","grammar:344:ex3:words:2:zh":"got up","grammar:344:ex3:words:2:note":"okimashita；masu-form past","grammar:344:ex3:words:2:pos":"verb","grammar:344:ex3:points:0":"一番 + adverb: the most …ly (一番早く = the earliest)","grammar:344:ex3:points:1":"i-adjective 〜く: becomes an adverb modifying a verb","grammar:344:ex4:trans":"What do you like best?","grammar:344:ex4:structure":"何 + が + 一番 + 好きですか. A question word as subject takes が, and 一番 marks the superlative.","grammar:344:ex4:words:0:zh":"what","grammar:344:ex4:words:0:note":"なに","grammar:344:ex4:words:0:pos":"question word","grammar:344:ex4:words:1:zh":"(object marker)","grammar:344:ex4:words:1:pos":"particle","grammar:344:ex4:words:2:zh":"the most","grammar:344:ex4:words:2:note":"いちばん","grammar:344:ex4:words:2:pos":"adverb","grammar:344:ex4:words:3:zh":"to like","grammar:344:ex4:words:3:note":"すき","grammar:344:ex4:words:3:pos":"na-adjective","grammar:344:ex4:words:4:zh":"is","grammar:344:ex4:words:4:pos":"copula","grammar:344:ex4:words:5:zh":"(question)","grammar:344:ex4:words:5:pos":"particle","grammar:344:ex4:points:0":"question word + が: 何が (what…)","grammar:344:ex4:points:1":"一番好きですか: do you like … best?","grammar:344:ex5:trans":"(This is) the place I most want to go.","grammar:344:ex5:structure":"一番 + 〔verb たい〕 + noun + です. 「一番行きたい場所」 = the place I most want to go; the たい form modifies the noun.","grammar:344:ex5:words:0:zh":"the most","grammar:344:ex5:words:0:note":"いちばん","grammar:344:ex5:words:0:pos":"adverb","grammar:344:ex5:words:1:zh":"want to go","grammar:344:ex5:words:1:note":"ikitai；〜たい expresses desire","grammar:344:ex5:words:1:pos":"verb","grammar:344:ex5:words:2:zh":"place","grammar:344:ex5:words:2:note":"ばしょ","grammar:344:ex5:words:2:pos":"noun","grammar:344:ex5:words:3:zh":"is","grammar:344:ex5:words:3:pos":"copula","grammar:344:ex5:points:0":"〜たい can modify a noun: 行きたい場所 (a place one wants to go)","grammar:344:ex5:points:1":"一番 + たい: most want to…","exam:344:zh":"Five of us ran, and I reached the finish before anyone else, so I was first.","exam:344:why":"Reaching the finish before everyone else makes you 「一番」. 「二番」 means second, which would require someone to have finished first."},"357":{"example:357:exzh":"Do it now!","example:357:exzh2":"If you tell me to do it, I'll do it.","example:357:exzh3":"I was told to do anything.","example:357:exzh4":"I don't like being ordered to do things.","example:357:exzh5":"Good grief, it's finally over.","grammar:357:ex:trans":"Hurry up and do it!","grammar:357:ex:structure":"〜やれ！","grammar:357:ex:explain":"The key is 「やれ」, the imperative form of the verb 「やる」 (to do). The tone is rough and forceful — it directly orders someone to do it, and it's mostly used from a superior to a subordinate, when angry, or in an emergency; it's never used in polite situations. The 「早く」 in front is the adverb meaning 「quickly, right away.」 So the whole sentence 「早くやれ！」 means 「Hurry up and do it!」 For godan (u-) verbs, the imperative form changes the final u-row sound to the e-row (やる → やれ, 行く → 行け), and they all sound forceful.","grammar:357:ex:words:0:zh":"quickly","grammar:357:ex:words:0:note":"はやく","grammar:357:ex:words:0:pos":"adverb","grammar:357:ex:words:1:zh":"do it","grammar:357:ex:words:1:pos":"verb","grammar:357:ex:points:0":"❗やれ: the imperative form of やる, 「Do it!」 (rough command).","grammar:357:ex:points:1":"早く: quickly.","grammar:357:ex2:trans":"If you tell me to do it, I'll do it.","grammar:357:ex2:structure":"〜というなら、〜ます","grammar:357:ex2:words:0:zh":"do it","grammar:357:ex2:words:0:pos":"verb","grammar:357:ex2:words:1:zh":"say that","grammar:357:ex2:words:1:pos":"set phrase","grammar:357:ex2:words:2:zh":"if","grammar:357:ex2:words:2:pos":"particle","grammar:357:ex2:words:3:zh":"do","grammar:357:ex2:words:3:pos":"verb","grammar:357:ex2:points:0":"〜というなら: if (someone) says they want you to…","grammar:357:ex2:points:1":"やります: to do (the polite form of やる).","grammar:357:ex3:trans":"I was told to do anything.","grammar:357:ex3:structure":"〜やれと言われた","grammar:357:ex3:words:0:zh":"anything","grammar:357:ex3:words:0:note":"なんでも","grammar:357:ex3:words:0:pos":"pronoun","grammar:357:ex3:words:1:zh":"do it","grammar:357:ex3:words:1:pos":"verb","grammar:357:ex3:words:2:zh":"(quotation)","grammar:357:ex3:words:2:pos":"particle","grammar:357:ex3:words:3:zh":"is said","grammar:357:ex3:words:3:note":"いわれた (passive form)","grammar:357:ex3:words:3:pos":"verb","grammar:357:ex3:points:0":"何でも: anything, whatever.","grammar:357:ex3:points:1":"〜と言われた: was told (to)… (passive form).","grammar:357:ex4:trans":"I don't like being ordered to do it.","grammar:357:ex4:structure":"〜られるのは嫌だ","grammar:357:ex4:words:0:zh":"do it","grammar:357:ex4:words:0:pos":"verb","grammar:357:ex4:words:1:zh":"(quotation)","grammar:357:ex4:words:1:pos":"particle","grammar:357:ex4:words:2:zh":"being ordered","grammar:357:ex4:words:2:note":"めいじられる (passive form)","grammar:357:ex4:words:2:pos":"verb","grammar:357:ex4:words:3:zh":"(nominalizer)","grammar:357:ex4:words:3:pos":"particle","grammar:357:ex4:words:4:zh":"(topic)","grammar:357:ex4:words:4:pos":"particle","grammar:357:ex4:words:5:zh":"unpleasant, annoying","grammar:357:ex4:words:5:note":"いや","grammar:357:ex4:words:5:pos":"na-adjective","grammar:357:ex4:words:6:zh":"is","grammar:357:ex4:words:6:pos":"copula","grammar:357:ex4:points:0":"命じられる: to be ordered (passive form).","grammar:357:ex4:points:1":"〜のは嫌だ: to dislike (doing)…","grammar:357:ex5:trans":"Phew, it's finally over.","grammar:357:ex5:structure":"やれやれ、〜た","grammar:357:ex5:words:0:zh":"phew / oh boy","grammar:357:ex5:words:0:pos":"interjection","grammar:357:ex5:words:1:zh":"finished","grammar:357:ex5:words:1:note":"おわった","grammar:357:ex5:words:1:pos":"verb","grammar:357:ex5:points:0":"やれやれ: (with relief / resignation) phew, oh boy (interjection).","grammar:357:ex5:points:1":"終わる → 終わった."},"360":{"example:360:exzh":"His voice faded away.","example:360:exzh2":"The lights went out.","example:360:exzh3":"Faded memories.","example:360:exzh4":"Her smile disappeared.","example:360:exzh5":"The smoke faded into the sky.","grammar:360:ex:trans":"His voice disappeared.","grammar:360:ex:structure":"〜が消えた","grammar:360:ex:explain":"「消える（きえる）」 is an intransitive verb meaning to disappear, to go out, to be gone (of a sound); its subject takes 「が」, so 「声が消える」 means a voice disappears. It pairs with the transitive 「消す（けす）」, meaning to turn off, remove, or erase: use 「消す」 when someone actively turns something off or wipes it out, and 「消える」 when something vanishes on its own. 「消えた」 is the plain past (drop る from the ichidan verb and add た). The whole sentence means his voice disappeared. Memorize the transitive/intransitive pair together.","grammar:360:ex:words:0:zh":"he","grammar:360:ex:words:0:note":"かれ","grammar:360:ex:words:0:pos":"pronoun","grammar:360:ex:words:1:zh":"'s","grammar:360:ex:words:1:pos":"particle","grammar:360:ex:words:2:zh":"voice","grammar:360:ex:words:2:note":"こえ","grammar:360:ex:words:2:pos":"noun","grammar:360:ex:words:3:zh":"(nominative)","grammar:360:ex:words:3:pos":"particle","grammar:360:ex:words:4:zh":"Disappeared","grammar:360:ex:words:4:note":"きえた","grammar:360:ex:words:4:pos":"verb","grammar:360:ex:points:0":"❗「消える（きえる）」: to disappear, to go out (intransitive verb); vs. 「消す」 (transitive, to turn off / erase); 「声が消える」 = a voice disappears.","grammar:360:ex:points:1":"「声が消える」: a voice disappears.","grammar:360:ex2:trans":"The light went out.","grammar:360:ex2:structure":"〜が消えました","grammar:360:ex2:words:0:zh":"light","grammar:360:ex2:words:0:note":"あかり","grammar:360:ex2:words:0:pos":"noun","grammar:360:ex2:words:1:zh":"(nominative)","grammar:360:ex2:words:1:pos":"particle","grammar:360:ex2:words:2:zh":"went out","grammar:360:ex2:words:2:note":"きえました","grammar:360:ex2:words:2:pos":"verb","grammar:360:ex2:points:0":"❗「明かりが消える」: the light goes out (「消える」 is intransitive); 明かり = light.","grammar:360:ex2:points:1":"「明かりが消える」: the light goes out.","grammar:360:ex3:trans":"Memories that have faded away.","grammar:360:ex3:structure":"消えてしまった思い出","grammar:360:ex3:words:0:zh":"disappear","grammar:360:ex3:words:0:note":"きえて","grammar:360:ex3:words:0:pos":"verb","grammar:360:ex3:words:1:zh":"(with regret)","grammar:360:ex3:words:1:pos":"auxiliary verb","grammar:360:ex3:words:2:zh":"memories","grammar:360:ex3:words:2:note":"おもいで","grammar:360:ex3:words:2:pos":"noun","grammar:360:ex3:points:0":"❗〜てしまった: …-ed (with regret); 「消えた思い出」 = memories that are gone.","grammar:360:ex3:points:1":"「消えた思い出」: memories that are gone.","grammar:360:ex4:trans":"Her smile disappeared.","grammar:360:ex4:structure":"〜が消えた","grammar:360:ex4:words:0:zh":"she","grammar:360:ex4:words:0:note":"かのじょ","grammar:360:ex4:words:0:pos":"pronoun","grammar:360:ex4:words:1:zh":"'s","grammar:360:ex4:words:1:pos":"particle","grammar:360:ex4:words:2:zh":"Smile","grammar:360:ex4:words:2:note":"えがお","grammar:360:ex4:words:2:pos":"noun","grammar:360:ex4:words:3:zh":"(nominative)","grammar:360:ex4:words:3:pos":"particle","grammar:360:ex4:words:4:zh":"Disappeared","grammar:360:ex4:words:4:note":"きえた","grammar:360:ex4:words:4:pos":"verb","grammar:360:ex4:points:0":"❗「笑顔が消える」: a smile disappears; 笑顔 = smile.","grammar:360:ex4:points:1":"「笑顔が消える」: a smile disappears.","grammar:360:ex5:trans":"The smoke faded away into the sky.","grammar:360:ex5:structure":"〜が〜に消えていった","grammar:360:ex5:words:0:zh":"smoke","grammar:360:ex5:words:0:note":"けむり","grammar:360:ex5:words:0:pos":"noun","grammar:360:ex5:words:1:zh":"(nominative)","grammar:360:ex5:words:1:pos":"particle","grammar:360:ex5:words:2:zh":"sky","grammar:360:ex5:words:2:note":"そら","grammar:360:ex5:words:2:pos":"noun","grammar:360:ex5:words:3:zh":"(the destination point)","grammar:360:ex5:words:3:pos":"particle","grammar:360:ex5:words:4:zh":"faded away","grammar:360:ex5:words:4:note":"きえていった","grammar:360:ex5:words:4:pos":"verb","grammar:360:ex5:points:0":"❗「消えていく」: to fade away gradually (「消える」 + 「いく」); 「煙が消える」 = the smoke clears.","grammar:360:ex5:points:1":"「煙が消える」: the smoke clears."},"368":{"example:368:exzh":"I want to go to America.","example:368:exzh2":"I'm very interested in American culture.","example:368:exzh3":"I like American food.","example:368:exzh4":"I plan to study abroad in America.","example:368:exzh5":"Studying American history.","grammar:368:ex:trans":"I want to go to America.","grammar:368:ex:structure":"〜に行きたい","grammar:368:ex:explain":"「アメリカ」 means 「America」, and the destination is marked with 「に」. The core is 「〜たい」, which attaches to a verb's stem to express the speaker's wish to do something; 「行く」 becomes 「行きたい」, 「want to go.」 In its conjugation 「行きたい」 behaves like an i-adjective (行きたいです, 行きたくない). The whole sentence is 「I want to go to America.」 Note that 「〜たい」 expresses your own desire; for a third person's desire, use 「〜たがっている」.","grammar:368:ex:words:0:zh":"America","grammar:368:ex:words:0:note":"loanword","grammar:368:ex:words:0:pos":"noun","grammar:368:ex:words:1:zh":"(destination)","grammar:368:ex:words:1:pos":"particle","grammar:368:ex:words:2:zh":"want to go","grammar:368:ex:words:2:note":"いきたい","grammar:368:ex:words:2:pos":"verb","grammar:368:ex:points:0":"アメリカ: America.","grammar:368:ex:points:1":"行く → 行きたい（〜たい）.","grammar:368:ex2:trans":"I'm very interested in American culture.","grammar:368:ex2:structure":"〜に興味がある","grammar:368:ex2:words:0:zh":"America","grammar:368:ex2:words:0:note":"loanword","grammar:368:ex2:words:0:pos":"noun","grammar:368:ex2:words:1:zh":"'s","grammar:368:ex2:words:1:pos":"particle","grammar:368:ex2:words:2:zh":"culture","grammar:368:ex2:words:2:note":"ぶんか","grammar:368:ex2:words:2:pos":"noun","grammar:368:ex2:words:3:zh":"(object)","grammar:368:ex2:words:3:pos":"particle","grammar:368:ex2:words:4:zh":"interest","grammar:368:ex2:words:4:note":"きょうみ","grammar:368:ex2:words:4:pos":"noun","grammar:368:ex2:words:5:zh":"(nominative)","grammar:368:ex2:words:5:pos":"particle","grammar:368:ex2:words:6:zh":"there is / are","grammar:368:ex2:words:6:pos":"verb","grammar:368:ex2:points:0":"❗〜に興味がある: to be interested in… (the target takes に).","grammar:368:ex2:points:1":"アメリカの文化: American culture.","grammar:368:ex3:trans":"I like American food.","grammar:368:ex3:structure":"〜が好き","grammar:368:ex3:words:0:zh":"America","grammar:368:ex3:words:0:note":"loanword","grammar:368:ex3:words:0:pos":"noun","grammar:368:ex3:words:1:zh":"'s","grammar:368:ex3:words:1:pos":"particle","grammar:368:ex3:words:2:zh":"food","grammar:368:ex3:words:2:note":"たべもの","grammar:368:ex3:words:2:pos":"noun","grammar:368:ex3:words:3:zh":"(object)","grammar:368:ex3:words:3:pos":"particle","grammar:368:ex3:words:4:zh":"to like","grammar:368:ex3:words:4:note":"すき","grammar:368:ex3:words:4:pos":"na-adjective","grammar:368:ex3:points:0":"アメリカの食べ物: American food.","grammar:368:ex3:points:1":"The object of 「好き」 takes が.","grammar:368:ex4:trans":"I plan to study abroad in America.","grammar:368:ex4:structure":"〜で〜する予定です","grammar:368:ex4:words:0:zh":"America","grammar:368:ex4:words:0:note":"loanword","grammar:368:ex4:words:0:pos":"noun","grammar:368:ex4:words:1:zh":"(place of the action)","grammar:368:ex4:words:1:pos":"particle","grammar:368:ex4:words:2:zh":"study abroad","grammar:368:ex4:words:2:note":"りゅうがくする","grammar:368:ex4:words:2:pos":"verb","grammar:368:ex4:words:3:zh":"plan","grammar:368:ex4:words:3:note":"よてい","grammar:368:ex4:words:3:pos":"noun","grammar:368:ex4:words:4:zh":"(polite form)","grammar:368:ex4:words:4:pos":"copula","grammar:368:ex4:points:0":"❓で: the place where the activity of studying abroad happens (in America).","grammar:368:ex4:points:1":"〜予定です: is scheduled to…","grammar:368:ex5:trans":"Study American history.","grammar:368:ex5:structure":"〜を学ぶ","grammar:368:ex5:words:0:zh":"America","grammar:368:ex5:words:0:note":"loanword","grammar:368:ex5:words:0:pos":"noun","grammar:368:ex5:words:1:zh":"'s","grammar:368:ex5:words:1:pos":"particle","grammar:368:ex5:words:2:zh":"history","grammar:368:ex5:words:2:note":"れきし","grammar:368:ex5:words:2:pos":"noun","grammar:368:ex5:words:3:zh":"(object marker)","grammar:368:ex5:words:3:pos":"particle","grammar:368:ex5:words:4:zh":"study","grammar:368:ex5:words:4:note":"まなぶ","grammar:368:ex5:words:4:pos":"verb","grammar:368:ex5:points:0":"アメリカの歴史: American history.","grammar:368:ex5:points:1":"学ぶ: to learn (more written-style than 勉強する).","exam:368:zh":"Washington, D.C. is the capital of America.","exam:368:why":"Washington, D.C. is the capital of 「アメリカ」. 「カナダ」 is also a North American country, but its capital isn't Washington, D.C."},"369":{"example:369:exzh":"My team is strong.","example:369:exzh2":"Cooperate as a team.","example:369:exzh3":"I joined a new team.","example:369:exzh4":"The team's goal has been achieved.","example:369:exzh5":"Good teamwork is needed.","grammar:369:ex:trans":"My team is strong.","grammar:369:ex:structure":"〜のチームは〜","grammar:369:ex:explain":"「チーム」 is a loanword from team, meaning 「team, squad.」 「私のチーム」 is modified with 「の」, 「my team,」 and 「は」 marks it as the topic. 「強い」 is the i-adjective 「strong,」 used here in plain form with no です at the end. The whole sentence is 「My team is strong.」 An i-adjective can end a sentence as a predicate on its own (強い); add 「です」 to be polite (強いです). Loanwords are very common in Japanese and are usually written in katakana.","grammar:369:ex:words:0:zh":"I","grammar:369:ex:words:0:note":"わたし","grammar:369:ex:words:0:pos":"pronoun","grammar:369:ex:words:1:zh":"'s","grammar:369:ex:words:1:pos":"particle","grammar:369:ex:words:2:zh":"team","grammar:369:ex:words:2:note":"loanword","grammar:369:ex:words:2:pos":"noun","grammar:369:ex:words:3:zh":"(topic)","grammar:369:ex:words:3:pos":"particle","grammar:369:ex:words:4:zh":"strong","grammar:369:ex:words:4:note":"つよい","grammar:369:ex:words:4:pos":"adjective","grammar:369:ex:points:0":"チーム: team.","grammar:369:ex:points:1":"強い: strong (i-adjective).","grammar:369:ex2:trans":"Cooperate as a team.","grammar:369:ex2:structure":"チームで〜する","grammar:369:ex2:words:0:zh":"team","grammar:369:ex2:words:0:note":"loanword","grammar:369:ex2:words:0:pos":"noun","grammar:369:ex2:words:1:zh":"(whole / scope)","grammar:369:ex2:words:1:pos":"particle","grammar:369:ex2:words:2:zh":"cooperate","grammar:369:ex2:words:2:note":"きょうりょくする","grammar:369:ex2:words:2:pos":"verb","grammar:369:ex2:points:0":"❓チームで: as a team (together) (で marks the whole group).","grammar:369:ex2:points:1":"協力する: to cooperate, to work together.","grammar:369:ex3:trans":"I joined a new team.","grammar:369:ex3:structure":"〜に参加した","grammar:369:ex3:words:0:zh":"new","grammar:369:ex3:words:0:note":"あたらしい","grammar:369:ex3:words:0:pos":"adjective","grammar:369:ex3:words:1:zh":"team","grammar:369:ex3:words:1:note":"loanword","grammar:369:ex3:words:1:pos":"noun","grammar:369:ex3:words:2:zh":"(object)","grammar:369:ex3:words:2:pos":"particle","grammar:369:ex3:words:3:zh":"attended","grammar:369:ex3:words:3:note":"さんかした","grammar:369:ex3:words:3:pos":"verb","grammar:369:ex3:points:0":"〜に参加する: to join… (the target takes に).","grammar:369:ex3:points:1":"参加する→参加した。","grammar:369:ex4:trans":"The team's goal was achieved.","grammar:369:ex4:structure":"〜を達成した","grammar:369:ex4:words:0:zh":"team","grammar:369:ex4:words:0:note":"loanword","grammar:369:ex4:words:0:pos":"noun","grammar:369:ex4:words:1:zh":"'s","grammar:369:ex4:words:1:pos":"particle","grammar:369:ex4:words:2:zh":"goal","grammar:369:ex4:words:2:note":"もくひょう","grammar:369:ex4:words:2:pos":"noun","grammar:369:ex4:words:3:zh":"(object marker)","grammar:369:ex4:words:3:pos":"particle","grammar:369:ex4:words:4:zh":"achieved","grammar:369:ex4:words:4:note":"たっせいした","grammar:369:ex4:words:4:pos":"verb","grammar:369:ex4:points:0":"目標を達成する: to achieve a goal.","grammar:369:ex4:points:1":"チームの目標: the team's goal.","grammar:369:ex5:trans":"Good teamwork is needed.","grammar:369:ex5:structure":"〜が必要だ","grammar:369:ex5:words:0:zh":"good","grammar:369:ex5:words:0:note":"いい","grammar:369:ex5:words:0:pos":"adjective","grammar:369:ex5:words:1:zh":"teamwork","grammar:369:ex5:words:1:note":"loanword","grammar:369:ex5:words:1:pos":"noun","grammar:369:ex5:words:2:zh":"(object)","grammar:369:ex5:words:2:pos":"particle","grammar:369:ex5:words:3:zh":"necessary","grammar:369:ex5:words:3:note":"ひつよう","grammar:369:ex5:words:3:pos":"na-adjective","grammar:369:ex5:words:4:zh":"is","grammar:369:ex5:words:4:pos":"copula","grammar:369:ex5:points:0":"チームワーク: teamwork.","grammar:369:ex5:points:1":"〜が必要だ: … is needed."},"370":{"example:370:exzh":"Food connoisseurs gather at this restaurant.","example:370:exzh2":"It's necessary to consult a food connoisseur.","example:370:exzh3":"He's a food connoisseur.","example:370:exzh4":"Let's learn how to make it from a food connoisseur.","example:370:exzh5":"If you're a connoisseur of food, you should know this restaurant."},"371":{"example:371:exzh":"His words were harsh.","example:371:exzh2":"The weather is terrible.","example:371:exzh3":"This incident is awful.","example:371:exzh4":"I went through a rough time.","example:371:exzh5":"He said something cruel."},"374":{"example:374:exzh":"I'm studying Japanese.","example:374:exzh2":"Studying many languages is fun.","example:374:exzh3":"He can speak many languages.","example:374:exzh4":"Learning languages is important.","example:374:exzh5":"Every word has its own characteristics.","grammar:374:ex:trans":"I'm studying Japanese.","grammar:374:ex:structure":"〜を勉強しています","grammar:374:ex:explain":"The key is the suffix 「語（ご）」, which attaches to country names and the like to form language names: 「日本＋語＝日本語」 (Japanese). The same works for 「英語、中国語」. The object takes 「を」. 「勉強する」 means 「to study, to study hard,」 and 「〜ている」 shows an action in progress, so 「勉強しています」 is 「am studying.」 The whole sentence is 「I'm studying Japanese.」 「〜語」 is a handy word-building pattern — when you see it, you know it's the name of a language.","grammar:374:ex:words:0:zh":"Japanese","grammar:374:ex:words:0:note":"にほんご","grammar:374:ex:words:0:pos":"noun","grammar:374:ex:words:1:zh":"(object marker)","grammar:374:ex:words:1:pos":"particle","grammar:374:ex:words:2:zh":"am studying","grammar:374:ex:words:2:note":"べんきょうしています","grammar:374:ex:words:2:pos":"verb","grammar:374:ex:points:1":"〜ている: ongoing action.","grammar:374:ex2:trans":"Learning many languages is fun.","grammar:374:ex2:structure":"〜と楽しいです","grammar:374:ex2:words:0:zh":"a lot","grammar:374:ex2:words:0:note":"おおく","grammar:374:ex2:words:0:pos":"noun","grammar:374:ex2:words:1:zh":"'s","grammar:374:ex2:words:1:pos":"particle","grammar:374:ex2:words:2:zh":"language / word","grammar:374:ex2:words:2:note":"ご","grammar:374:ex2:words:2:pos":"noun","grammar:374:ex2:words:3:zh":"(object marker)","grammar:374:ex2:words:3:pos":"particle","grammar:374:ex2:words:4:zh":"study","grammar:374:ex2:words:4:note":"まなぶ","grammar:374:ex2:words:4:pos":"verb","grammar:374:ex2:words:5:zh":"(condition)","grammar:374:ex2:words:5:pos":"particle","grammar:374:ex2:words:6:zh":"interesting","grammar:374:ex2:words:6:note":"たのしい","grammar:374:ex2:words:6:pos":"adjective","grammar:374:ex2:words:7:zh":"(polite form)","grammar:374:ex2:words:7:pos":"copula","grammar:374:ex2:points:0":"〜と: if/when…, then… (conditional).","grammar:374:ex2:points:1":"語（ご）: language, word.","grammar:374:ex3:trans":"He can speak several languages.","grammar:374:ex3:structure":"〜を話せます","grammar:374:ex3:words:0:zh":"he","grammar:374:ex3:words:0:note":"かれ","grammar:374:ex3:words:0:pos":"pronoun","grammar:374:ex3:words:1:zh":"(topic)","grammar:374:ex3:words:1:pos":"particle","grammar:374:ex3:words:2:zh":"various","grammar:374:ex3:words:2:note":"いろいろ","grammar:374:ex3:words:2:pos":"na-adjective","grammar:374:ex3:words:3:zh":"(attributive form)","grammar:374:ex3:words:3:pos":"auxiliary verb","grammar:374:ex3:words:4:zh":"languages","grammar:374:ex3:words:4:note":"ご","grammar:374:ex3:words:4:pos":"noun","grammar:374:ex3:words:5:zh":"(object marker)","grammar:374:ex3:words:5:pos":"particle","grammar:374:ex3:words:6:zh":"can speak","grammar:374:ex3:words:6:note":"はなせます","grammar:374:ex3:words:6:pos":"verb","grammar:374:ex3:points:0":"話せる: can speak (the potential form of 話す).","grammar:374:ex3:points:1":"色々な語: various languages.","grammar:374:ex4:trans":"Learning languages is important.","grammar:374:ex4:structure":"〜ことは大切です","grammar:374:ex4:words:0:zh":"languages","grammar:374:ex4:words:0:note":"げんご","grammar:374:ex4:words:0:pos":"noun","grammar:374:ex4:words:1:zh":"(object marker)","grammar:374:ex4:words:1:pos":"particle","grammar:374:ex4:words:2:zh":"study","grammar:374:ex4:words:2:note":"まなぶ","grammar:374:ex4:words:2:pos":"verb","grammar:374:ex4:words:3:zh":"(nominalizer)","grammar:374:ex4:words:3:pos":"noun","grammar:374:ex4:words:4:zh":"(topic)","grammar:374:ex4:words:4:pos":"particle","grammar:374:ex4:words:5:zh":"important","grammar:374:ex4:words:5:note":"たいせつ","grammar:374:ex4:words:5:pos":"na-adjective","grammar:374:ex4:words:6:zh":"(polite form)","grammar:374:ex4:words:6:pos":"copula","grammar:374:ex4:points:0":"言語（げんご）: language.","grammar:374:ex4:points:1":"verb ＋ こと: nominalizes the phrase so it can act as the subject.","grammar:374:ex5:trans":"Each word has its own characteristics.","grammar:374:ex5:structure":"〜には〜があります (〜 has 〜)","grammar:374:ex5:words:0:zh":"each","grammar:374:ex5:words:0:pos":"noun","grammar:374:ex5:words:1:zh":"'s","grammar:374:ex5:words:1:pos":"particle","grammar:374:ex5:words:2:zh":"languages","grammar:374:ex5:words:2:note":"ご","grammar:374:ex5:words:2:pos":"noun","grammar:374:ex5:words:3:zh":"(location of existence)","grammar:374:ex5:words:3:pos":"particle","grammar:374:ex5:words:4:zh":"(contrast)","grammar:374:ex5:words:4:pos":"particle","grammar:374:ex5:words:5:zh":"characteristics","grammar:374:ex5:words:5:note":"とくちょう","grammar:374:ex5:words:5:pos":"noun","grammar:374:ex5:words:6:zh":"(nominative)","grammar:374:ex5:words:6:pos":"particle","grammar:374:ex5:words:7:zh":"there is / are","grammar:374:ex5:words:7:pos":"verb","grammar:374:ex5:points:0":"それぞれの: each, every.","grammar:374:ex5:points:1":"〜には〜がある: … has…, there is… in…"},"375":{"example:375:exzh":"Mother is kind.","example:375:exzh2":"Her mother is good at cooking.","example:375:exzh3":"My mother is a teacher.","example:375:exzh4":"I'm grateful to my mother.","example:375:exzh5":"His mother is beautiful."},"377":{"example:377:exzh":"Where are you going?","example:377:exzh2":"Where does she live?","example:377:exzh3":"Where do we play?","example:377:exzh4":"Where is this place?","example:377:exzh5":"Where is that shop?","grammar:377:ex:trans":"Where are you going?","grammar:377:ex:structure":"どこに行きますか","grammar:377:ex:explain":"The question word 「どこ」 means 「where」 and asks about a place. 「どこに」 marks the destination with 「に」, so 「どこに行く」 is 「go where.」 「行きます」 is the polite form, and 「か」 turns it into a question. The whole sentence is 「Where are you going?」 The demonstrative set 「ここ（here）／そこ（there）／あそこ（over there）／どこ（where）」 forms a group, and 「どこ」 is its question word — you answer with one of the first three.","grammar:377:ex:words:0:zh":"where","grammar:377:ex:words:0:pos":"question word","grammar:377:ex:words:1:zh":"(destination)","grammar:377:ex:words:1:pos":"particle","grammar:377:ex:words:2:zh":"going to","grammar:377:ex:words:2:note":"いきますか","grammar:377:ex:words:2:pos":"verb","grammar:377:ex:points:0":"どこに: where to (destination).","grammar:377:ex:points:1":"行く → 行きます.","grammar:377:ex2:trans":"Where does she live?","grammar:377:ex2:structure":"どこに住んでいますか","grammar:377:ex2:words:0:zh":"she","grammar:377:ex2:words:0:note":"かのじょ","grammar:377:ex2:words:0:pos":"pronoun","grammar:377:ex2:words:1:zh":"(topic)","grammar:377:ex2:words:1:pos":"particle","grammar:377:ex2:words:2:zh":"where","grammar:377:ex2:words:2:pos":"question word","grammar:377:ex2:words:3:zh":"(location of existence)","grammar:377:ex2:words:3:pos":"particle","grammar:377:ex2:words:4:zh":"live (there)","grammar:377:ex2:words:4:note":"すんでいます","grammar:377:ex2:words:4:pos":"verb","grammar:377:ex2:words:5:zh":"(question)","grammar:377:ex2:words:5:pos":"particle","grammar:377:ex2:points:0":"どこに住んでいる: to live where.","grammar:377:ex2:points:1":"〜ている: a state.","grammar:377:ex3:trans":"Where will we play?","grammar:377:ex3:structure":"どこで〜ますか","grammar:377:ex3:words:0:zh":"where","grammar:377:ex3:words:0:pos":"question word","grammar:377:ex3:words:1:zh":"(place of the action)","grammar:377:ex3:words:1:pos":"particle","grammar:377:ex3:words:2:zh":"play","grammar:377:ex3:words:2:note":"あそびますか","grammar:377:ex3:words:2:pos":"verb","grammar:377:ex3:points:0":"❓どこで: where (the place of an action takes で, ≠ どこに).","grammar:377:ex3:points:1":"遊ぶ→遊びます。","grammar:377:ex4:trans":"Where is this place?","grammar:377:ex4:structure":"〜はどこですか","grammar:377:ex4:words:0:zh":"here","grammar:377:ex4:words:0:pos":"pronoun","grammar:377:ex4:words:1:zh":"(topic)","grammar:377:ex4:words:1:pos":"particle","grammar:377:ex4:words:2:zh":"where","grammar:377:ex4:words:2:pos":"question word","grammar:377:ex4:words:3:zh":"is","grammar:377:ex4:words:3:pos":"copula","grammar:377:ex4:words:4:zh":"(question)","grammar:377:ex4:words:4:pos":"particle","grammar:377:ex4:points:0":"ここはどこ: where is this place.","grammar:377:ex4:points:1":"どこですか: where / what place (is it).","grammar:377:ex5:trans":"Where is that store?","grammar:377:ex5:structure":"〜はどこにありますか","grammar:377:ex5:words:0:zh":"that","grammar:377:ex5:words:0:pos":"pre-noun adjectival","grammar:377:ex5:words:1:zh":"shop","grammar:377:ex5:words:1:note":"みせ","grammar:377:ex5:words:1:pos":"noun","grammar:377:ex5:words:2:zh":"(topic)","grammar:377:ex5:words:2:pos":"particle","grammar:377:ex5:words:3:zh":"where","grammar:377:ex5:words:3:pos":"question word","grammar:377:ex5:words:4:zh":"(location of existence)","grammar:377:ex5:words:4:pos":"particle","grammar:377:ex5:words:5:zh":"there is / are","grammar:377:ex5:words:5:pos":"verb","grammar:377:ex5:words:6:zh":"(question)","grammar:377:ex5:words:6:pos":"particle","grammar:377:ex5:points:0":"❓どこにありますか: where is it (inanimate things take ある).","grammar:377:ex5:points:1":"その店: that store.","exam:377:zh":"I didn't know the way to the station, so I asked someone nearby, \"Where is the station?\"","exam:377:why":"To ask about a place, use 「どこ」. 「いつ」 asks about time and can't get you the station's location."},"378":{"example:378:exzh":"He seems like a student.","example:378:exzh2":"I heard that movie is interesting.","example:378:exzh3":"I heard she is a professional painter.","example:378:exzh4":"They act like a child.","example:378:exzh5":"He behaves like an adult.","grammar:378:ex:trans":"He really seems like a student.","grammar:378:ex:structure":"〜らしいです","grammar:378:ex:explain":"Here 「〜らしい」 has the typical-of, having-the-look-of meaning: attached to a noun, it means having the qualities of …, worthy of the name, true to type, so 「学生らしい」 means the way a student should be, very much a student. This is different from the conjecture 「らしい」 (I hear that, it seems), so you have to judge from context. Here 「彼は学生らしいです」 means he really is like a student. The whole sentence means he really seems like a student. A similar example is 「男らしい」.","grammar:378:ex:words:0:zh":"he","grammar:378:ex:words:0:note":"かれ","grammar:378:ex:words:0:pos":"pronoun","grammar:378:ex:words:1:zh":"(topic)","grammar:378:ex:words:1:pos":"particle","grammar:378:ex:words:2:zh":"student","grammar:378:ex:words:2:note":"がくせい","grammar:378:ex:words:2:pos":"noun","grammar:378:ex:words:3:zh":"having the look of …","grammar:378:ex:words:3:pos":"auxiliary verb","grammar:378:ex:words:4:zh":"(polite form)","grammar:378:ex:words:4:pos":"copula","grammar:378:ex:points:0":"❗〜らしい (1): having the typical look of …, true to type (noun + らしい, e.g. 「学生らしい」 = just like a student).","grammar:378:ex:points:1":"「学生らしい」: just like a student.","grammar:378:ex2:trans":"I hear that movie is interesting.","grammar:378:ex2:structure":"〜らしい","grammar:378:ex2:words:0:zh":"that","grammar:378:ex2:words:0:pos":"pre-noun adjectival","grammar:378:ex2:words:1:zh":"movie","grammar:378:ex2:words:1:note":"えいが","grammar:378:ex2:words:1:pos":"noun","grammar:378:ex2:words:2:zh":"(topic)","grammar:378:ex2:words:2:pos":"particle","grammar:378:ex2:words:3:zh":"interesting","grammar:378:ex2:words:3:note":"おもしろい","grammar:378:ex2:words:3:pos":"adjective","grammar:378:ex2:words:4:zh":"I hear (that)","grammar:378:ex2:words:4:pos":"auxiliary verb","grammar:378:ex2:points:0":"❗〜らしい (2): I hear that…, they say that… (hearsay; follows the plain form, e.g. 「面白いらしい」 = I hear it is interesting).","grammar:378:ex2:points:1":"「面白いらしい」: I hear it is interesting.","grammar:378:ex3:trans":"I hear she is a professional artist.","grammar:378:ex3:structure":"〜らしい","grammar:378:ex3:words:0:zh":"she","grammar:378:ex3:words:0:note":"かのじょ","grammar:378:ex3:words:0:pos":"pronoun","grammar:378:ex3:words:1:zh":"(topic)","grammar:378:ex3:words:1:pos":"particle","grammar:378:ex3:words:2:zh":"specialty","grammar:378:ex3:words:2:note":"loanword","grammar:378:ex3:words:2:pos":"noun","grammar:378:ex3:words:3:zh":"'s","grammar:378:ex3:words:3:pos":"particle","grammar:378:ex3:words:4:zh":"painter","grammar:378:ex3:words:4:note":"えかき","grammar:378:ex3:words:4:pos":"noun","grammar:378:ex3:words:5:zh":"I hear (that)","grammar:378:ex3:words:5:pos":"auxiliary verb","grammar:378:ex3:points:0":"❗〜らしい (hearsay): they say that…; 「プロの絵描き」 = professional artist.","grammar:378:ex3:points:1":"〜らしい: I hear that","grammar:378:ex4:trans":"To act in a childlike way.","grammar:378:ex4:structure":"〜らしい〜をします","grammar:378:ex4:words:0:zh":"child","grammar:378:ex4:words:0:note":"こども","grammar:378:ex4:words:0:pos":"noun","grammar:378:ex4:words:1:zh":"like…","grammar:378:ex4:words:1:pos":"auxiliary verb","grammar:378:ex4:words:2:zh":"actions","grammar:378:ex4:words:2:note":"こうどう","grammar:378:ex4:words:2:pos":"noun","grammar:378:ex4:words:3:zh":"(object marker)","grammar:378:ex4:words:3:pos":"particle","grammar:378:ex4:words:4:zh":"do","grammar:378:ex4:words:4:pos":"verb","grammar:378:ex4:points:0":"❗「子供らしい」: fitting for a child, childlike (noun + らしい, the typical-of sense).","grammar:378:ex4:points:1":"「子供らしい」: childlike.","grammar:378:ex5:trans":"He behaves like an adult.","grammar:378:ex5:structure":"〜らしい〜をします","grammar:378:ex5:words:0:zh":"he","grammar:378:ex5:words:0:note":"かれ","grammar:378:ex5:words:0:pos":"pronoun","grammar:378:ex5:words:1:zh":"(topic)","grammar:378:ex5:words:1:pos":"particle","grammar:378:ex5:words:2:zh":"adult","grammar:378:ex5:words:2:note":"おとな","grammar:378:ex5:words:2:pos":"noun","grammar:378:ex5:words:3:zh":"like…","grammar:378:ex5:words:3:pos":"auxiliary verb","grammar:378:ex5:words:4:zh":"behave","grammar:378:ex5:words:4:note":"ふるまい","grammar:378:ex5:words:4:pos":"noun","grammar:378:ex5:words:5:zh":"(object marker)","grammar:378:ex5:words:5:pos":"particle","grammar:378:ex5:words:6:zh":"do","grammar:378:ex5:words:6:pos":"verb","grammar:378:ex5:points:0":"❗「大人らしい」: adult-like (noun + らしい); 振る舞い = behavior.","grammar:378:ex5:points:1":"「大人らしい」: adult-like."},"389":{"example:389:exzh":"In China, yuan is used.","example:389:exzh2":"You can pay in yuan at this shop.","example:389:exzh3":"I exchanged yuan for yen at the airport.","example:389:exzh4":"How much is one yuan in Japanese yen?","example:389:exzh5":"Before the trip, I got some yuan ready.","grammar:389:ex:trans":"In China, people use yuan.","grammar:389:ex:structure":"place では + noun を + verb ます","grammar:389:ex:explain":"When 「元」 is read 「げん」, it refers to the Chinese currency unit; formally it is often called 「人民元」. The sentence 「中国では元を使います」 explains which currency a country uses, with 「では」 limiting the scope to China. When exchanging money, people also often say 「元を円に替える」 (to change yuan into yen).","grammar:389:ex:words:0:zh":"China","grammar:389:ex:words:0:note":"Chūgoku；country name","grammar:389:ex:words:0:pos":"noun","grammar:389:ex:words:1:zh":"exist","grammar:389:ex:words:1:pos":"particle","grammar:389:ex:words:2:zh":"marks the topic","grammar:389:ex:words:2:pos":"particle","grammar:389:ex:words:3:zh":"the yuan (Chinese currency)","grammar:389:ex:words:3:note":"gen；the Chinese currency unit","grammar:389:ex:words:3:pos":"noun","grammar:389:ex:words:4:zh":"object marker","grammar:389:ex:words:4:pos":"particle","grammar:389:ex:words:5:zh":"use","grammar:389:ex:words:5:note":"つかい; the masu-form stem of 「使う」","grammar:389:ex:words:5:pos":"verb","grammar:389:ex:words:6:zh":"polite ending","grammar:389:ex:words:6:pos":"auxiliary verb","grammar:389:ex:points:0":"In 「元を使います」, 「元」 refers to the Chinese currency unit (the yuan), and 「を使う」 means to use a certain currency.","grammar:389:ex:points:1":"In 「中国では」, 「で」 marks the area where the currency is used, and 「は」 presents it as the topic.","grammar:389:ex:points:2":"「使います」 is the polite form of 「使う」 and suits everyday explanations.","grammar:389:ex2:trans":"You can pay in yuan at this shop.","grammar:389:ex2:structure":"この + noun では + noun で + verb potential form ます","grammar:389:ex2:words:0:zh":"this","grammar:389:ex2:words:0:pos":"pre-noun adjectival","grammar:389:ex2:words:1:zh":"store","grammar:389:ex2:words:1:note":"みせ: shop","grammar:389:ex2:words:1:pos":"noun","grammar:389:ex2:words:2:zh":"exist","grammar:389:ex2:words:2:pos":"particle","grammar:389:ex2:words:3:zh":"marks the topic","grammar:389:ex2:words:3:pos":"particle","grammar:389:ex2:words:4:zh":"the yuan (Chinese currency)","grammar:389:ex2:words:4:note":"gen；the Chinese currency unit","grammar:389:ex2:words:4:pos":"noun","grammar:389:ex2:words:5:zh":"use","grammar:389:ex2:words:5:pos":"particle","grammar:389:ex2:words:6:zh":"can pay","grammar:389:ex2:words:6:note":"harai — harawu: haraw-eru stem: harae；the potential form stem of 払う","grammar:389:ex2:words:6:pos":"verb","grammar:389:ex2:words:7:zh":"polite ending","grammar:389:ex2:words:7:pos":"auxiliary verb","grammar:389:ex2:points:0":"「元で払えます」 means you can pay in yuan, with the marked word being the currency used for payment.","grammar:389:ex2:points:1":"The first 「で」 marks the location, and the second 「で」 marks the means.","grammar:389:ex2:points:2":"「払えます」 is the potential form, meaning can pay.","grammar:389:ex3:trans":"I changed yuan into yen at the airport.","grammar:389:ex3:structure":"place で + noun を + noun に + 替えました","grammar:389:ex3:words:0:zh":"airport","grammar:389:ex3:words:0:note":"くうこう；airport","grammar:389:ex3:words:0:pos":"noun","grammar:389:ex3:words:1:zh":"exist","grammar:389:ex3:words:1:pos":"particle","grammar:389:ex3:words:2:zh":"the yuan (Chinese currency)","grammar:389:ex3:words:2:note":"gen；the Chinese currency unit","grammar:389:ex3:words:2:pos":"noun","grammar:389:ex3:words:3:zh":"object marker","grammar:389:ex3:words:3:pos":"particle","grammar:389:ex3:words:4:zh":"yen","grammar:389:ex3:words:4:note":"en；the Japanese currency unit","grammar:389:ex3:words:4:pos":"noun","grammar:389:ex3:words:5:zh":"become","grammar:389:ex3:words:5:pos":"particle","grammar:389:ex3:words:6:zh":"exchange (currency)","grammar:389:ex3:words:6:note":"kae；the masu-form stem of 替える","grammar:389:ex3:words:6:pos":"verb","grammar:389:ex3:words:7:zh":"past polite ending","grammar:389:ex3:words:7:pos":"auxiliary verb","grammar:389:ex3:points:0":"「元を円に替えました」 means changed yuan into yen.","grammar:389:ex3:points:1":"「を」 marks the money being exchanged, and 「に」 marks the result of the exchange.","grammar:389:ex3:points:2":"「ました」 marks an action that took place in the past.","grammar:389:ex4:trans":"How much is one yuan in yen?","grammar:389:ex4:structure":"number + 元は + noun で + いくらですか","grammar:389:ex4:words:0:zh":"one","grammar:389:ex4:words:0:note":"いち","grammar:389:ex4:words:0:pos":"numeral","grammar:389:ex4:words:1:zh":"yuan (Chinese currency unit)","grammar:389:ex4:words:1:note":"gen；the Chinese currency unit","grammar:389:ex4:words:1:pos":"noun","grammar:389:ex4:words:2:zh":"marks the topic","grammar:389:ex4:words:2:pos":"particle","grammar:389:ex4:words:3:zh":"yen","grammar:389:ex4:words:3:note":"Nihon-en；Japanese currency","grammar:389:ex4:words:3:pos":"noun","grammar:389:ex4:words:4:zh":"calculated in…","grammar:389:ex4:words:4:pos":"particle","grammar:389:ex4:words:5:zh":"how much (money)","grammar:389:ex4:words:5:pos":"question word","grammar:389:ex4:words:6:zh":"is","grammar:389:ex4:words:6:pos":"copula","grammar:389:ex4:words:7:zh":"question","grammar:389:ex4:words:7:pos":"particle","grammar:389:ex4:points:0":"「一元」 is the number 「一」 plus the currency unit 「元」; the sentence asks how much one yuan is worth in yen.","grammar:389:ex4:points:1":"The 「で」 in 「日本円で」 marks the basis for conversion, meaning calculated in yen.","grammar:389:ex4:points:2":"「いくらですか」 is the basic question for asking an amount.","grammar:389:ex5:trans":"Before the trip, I got yuan ready.","grammar:389:ex5:structure":"time に + noun を + verb ました","grammar:389:ex5:words:0:zh":"travel / trip","grammar:389:ex5:words:0:note":"ryokō；trip","grammar:389:ex5:words:0:pos":"noun","grammar:389:ex5:words:1:zh":"before","grammar:389:ex5:words:1:note":"mae；before","grammar:389:ex5:words:1:pos":"noun","grammar:389:ex5:words:2:zh":"exist","grammar:389:ex5:words:2:pos":"particle","grammar:389:ex5:words:3:zh":"the yuan (Chinese currency)","grammar:389:ex5:words:3:note":"gen；the Chinese currency unit","grammar:389:ex5:words:3:pos":"noun","grammar:389:ex5:words:4:zh":"object marker","grammar:389:ex5:words:4:pos":"particle","grammar:389:ex5:words:5:zh":"prepare","grammar:389:ex5:words:5:note":"junbi shi；the masu-form stem of 準備する","grammar:389:ex5:words:5:pos":"verb","grammar:389:ex5:words:6:zh":"past polite ending","grammar:389:ex5:words:6:pos":"auxiliary verb","grammar:389:ex5:points:0":"「元を準備しました」 means getting yuan ready for the trip.","grammar:389:ex5:points:1":"In 「旅行前に」, 「に」 marks the time when the preparing took place.","grammar:389:ex5:points:2":"「準備しました」 is the polite past, showing the action is complete."},"390":{"example:390:exzh":"Long ago, there was a big forest here.","example:390:exzh2":"I like hearing stories from long ago.","example:390:exzh3":"She remembered an old friend.","example:390:exzh4":"In the past, children used to play outside.","example:390:exzh5":"I'd like to watch an old movie.","grammar:390:ex:trans":"Long ago, there was a big forest here.","grammar:390:ex:structure":"昔、〔place〕には + noun + が + ありました. The time noun 「昔」 opens the sentence, and this is an existence sentence in the past.","grammar:390:ex:explain":"The key word 「昔（むかし）」 means long ago, in the past; it is a time noun and often comes at the start of a sentence to set the scene. 「ここには」 means here (there used to be), with 「に」 marking the place of existence plus the topic marker 「は」. 「大きな森が」 uses 「が」 to introduce the subject, and 「大きな」 is a pre-noun adjectival. 「ありました」 is the polite past of 「ある」. The whole sentence means long ago, there was a big forest here. Putting a time noun first with a comma is a common way to open a Japanese narrative.","grammar:390:ex:words:0:zh":"in the past","grammar:390:ex:words:0:note":"mukashi；time noun","grammar:390:ex:words:0:pos":"noun","grammar:390:ex:words:1:zh":"here","grammar:390:ex:words:1:pos":"pronoun","grammar:390:ex:words:2:zh":"(the place where something exists)","grammar:390:ex:words:2:pos":"particle","grammar:390:ex:words:3:zh":"(emphasis)","grammar:390:ex:words:3:pos":"particle","grammar:390:ex:words:4:zh":"big","grammar:390:ex:words:4:note":"おおきな","grammar:390:ex:words:4:pos":"pre-noun adjectival","grammar:390:ex:words:5:zh":"forest","grammar:390:ex:words:5:note":"もり","grammar:390:ex:words:5:pos":"noun","grammar:390:ex:words:6:zh":"(nominative)","grammar:390:ex:words:6:pos":"particle","grammar:390:ex:words:7:zh":"there was","grammar:390:ex:words:7:note":"past existence","grammar:390:ex:words:7:pos":"verb","grammar:390:ex:points:0":"昔: long ago (a time noun, can go at the start of a sentence)","grammar:390:ex:points:1":"place には 〜がある: somewhere has …","grammar:390:ex2:trans":"I like listening to stories from long ago.","grammar:390:ex2:structure":"〔〜を聞く + の〕 + が + 好きです. 「の」 nominalizes 「聞く」, making it the object of liking.","grammar:390:ex2:words:0:zh":"in the old days","grammar:390:ex2:words:0:note":"むかし","grammar:390:ex2:words:0:pos":"noun","grammar:390:ex2:words:1:zh":"'s","grammar:390:ex2:words:1:pos":"particle","grammar:390:ex2:words:2:zh":"story","grammar:390:ex2:words:2:note":"はなし","grammar:390:ex2:words:2:pos":"noun","grammar:390:ex2:words:3:zh":"(object marker)","grammar:390:ex2:words:3:pos":"particle","grammar:390:ex2:words:4:zh":"listen","grammar:390:ex2:words:4:note":"kiku；dictionary form","grammar:390:ex2:words:4:pos":"verb","grammar:390:ex2:words:5:zh":"(nominalizer)","grammar:390:ex2:words:5:pos":"particle","grammar:390:ex2:words:6:zh":"(object marker)","grammar:390:ex2:words:6:pos":"particle","grammar:390:ex2:words:7:zh":"to like","grammar:390:ex2:words:7:note":"すき","grammar:390:ex2:words:7:pos":"na-adjective","grammar:390:ex2:words:8:zh":"(polite form)","grammar:390:ex2:words:8:pos":"copula","grammar:390:ex2:points:0":"verb + の + が好き: like doing…","grammar:390:ex2:points:1":"昔の話: a story from long ago","grammar:390:ex3:trans":"She remembered a friend from long ago.","grammar:390:ex3:structure":"nounは＋〔昔の友達〕＋を＋思い出しました. 「思い出す」 = to remember, to recall.","grammar:390:ex3:words:0:zh":"she","grammar:390:ex3:words:0:note":"かのじょ","grammar:390:ex3:words:0:pos":"pronoun","grammar:390:ex3:words:1:zh":"(topic marker)","grammar:390:ex3:words:1:pos":"particle","grammar:390:ex3:words:2:zh":"in the old days","grammar:390:ex3:words:2:note":"むかし","grammar:390:ex3:words:2:pos":"noun","grammar:390:ex3:words:3:zh":"'s","grammar:390:ex3:words:3:pos":"particle","grammar:390:ex3:words:4:zh":"friend","grammar:390:ex3:words:4:note":"ともだち","grammar:390:ex3:words:4:pos":"noun","grammar:390:ex3:words:5:zh":"(object marker)","grammar:390:ex3:words:5:pos":"particle","grammar:390:ex3:words:6:zh":"remembered","grammar:390:ex3:words:6:note":"おもいだしました","grammar:390:ex3:words:6:pos":"verb","grammar:390:ex3:points:0":"思い出す: to remember, to recall","grammar:390:ex3:points:1":"昔の友達: an old friend, a friend from the past","grammar:390:ex4:trans":"In the past, children used to play outside.","grammar:390:ex4:structure":"昔は＋nounが＋placeで＋verbていました. 「〜ていました」 expresses a past ongoing action or a past habit.","grammar:390:ex4:words:0:zh":"in the past","grammar:390:ex4:words:0:note":"むかし","grammar:390:ex4:words:0:pos":"noun","grammar:390:ex4:words:1:zh":"(topic marker)","grammar:390:ex4:words:1:pos":"particle","grammar:390:ex4:words:2:zh":"children","grammar:390:ex4:words:2:note":"こどもたち; 〜たち marks the plural","grammar:390:ex4:words:2:pos":"noun","grammar:390:ex4:words:3:zh":"(nominative)","grammar:390:ex4:words:3:pos":"particle","grammar:390:ex4:words:4:zh":"outside","grammar:390:ex4:words:4:note":"そと","grammar:390:ex4:words:4:pos":"noun","grammar:390:ex4:words:5:zh":"(place of the action)","grammar:390:ex4:words:5:pos":"particle","grammar:390:ex4:words:6:zh":"(past) were playing","grammar:390:ex4:words:6:note":"〜ていました expresses a past ongoing action or habit","grammar:390:ex4:words:6:pos":"verb","grammar:390:ex4:points:0":"〜ていました: was doing… (in the past, continuously or as a habit)","grammar:390:ex4:points:1":"で: the place where an action takes place","grammar:390:ex5:trans":"I want to see an old movie.","grammar:390:ex5:structure":"〔昔の映画〕＋を＋verbてみたいです. 「〜てみたい」 = to want to try doing…","grammar:390:ex5:words:0:zh":"in the past","grammar:390:ex5:words:0:note":"むかし","grammar:390:ex5:words:0:pos":"noun","grammar:390:ex5:words:1:zh":"'s","grammar:390:ex5:words:1:pos":"particle","grammar:390:ex5:words:2:zh":"movie","grammar:390:ex5:words:2:note":"えいが","grammar:390:ex5:words:2:pos":"noun","grammar:390:ex5:words:3:zh":"(object marker)","grammar:390:ex5:words:3:pos":"particle","grammar:390:ex5:words:4:zh":"want to try watching","grammar:390:ex5:words:4:note":"〜てみる＋たい: to want to try…","grammar:390:ex5:words:4:pos":"verb","grammar:390:ex5:words:5:zh":"(polite form)","grammar:390:ex5:words:5:pos":"copula","grammar:390:ex5:points:0":"〜てみたい: to want to try… (てみる＋たい)","grammar:390:ex5:points:1":"昔の映画: an old movie, a movie from the past"},"391":{"example:391:exzh":"The damage from the earthquake was very great.","example:391:exzh2":"We need to help the people who were affected.","example:391:exzh3":"This accident left many victims.","example:391:exzh4":"We're thinking about ways to minimize the damage.","example:391:exzh5":"The damage investigation has begun."},"392":{"example:392:exzh":"Jack is my friend.","example:392:exzh2":"Jack likes soccer.","example:392:exzh3":"Jack goes to school every day.","example:392:exzh4":"I'll hang out with Jack.","example:392:exzh5":"Jack is good at cooking.","grammar:392:ex:trans":"Jack is my friend.","grammar:392:ex:structure":"〜は〜の友達です","grammar:392:ex:explain":"「ジャック」 is the loanword name 「Jack」; foreign names and loanwords are usually written in katakana. 「〜は〜の友達です」 is a noun-predicate sentence, and 「私の友達」 is modified with 「の」, 「my friend.」 The whole sentence is 「Jack is my friend.」 Katakana is mainly used for loanwords, foreign names and place names, and onomatopoeia, so a word in katakana is often a hint that it's foreign or being emphasized.","grammar:392:ex:words:0:zh":"Jack","grammar:392:ex:words:0:note":"person's name","grammar:392:ex:words:0:pos":"noun","grammar:392:ex:words:1:zh":"(topic)","grammar:392:ex:words:1:pos":"particle","grammar:392:ex:words:2:zh":"I","grammar:392:ex:words:2:note":"わたし","grammar:392:ex:words:2:pos":"pronoun","grammar:392:ex:words:3:zh":"'s","grammar:392:ex:words:3:pos":"particle","grammar:392:ex:words:4:zh":"friend","grammar:392:ex:words:4:note":"ともだち","grammar:392:ex:words:4:pos":"noun","grammar:392:ex:words:5:zh":"is","grammar:392:ex:words:5:pos":"copula","grammar:392:ex:points:0":"ジャック: Jack (a foreign name).","grammar:392:ex:points:1":"私の友達: my friend.","grammar:392:ex2:trans":"Jack likes soccer.","grammar:392:ex2:structure":"〜は〜が好きです","grammar:392:ex2:words:0:zh":"Jack","grammar:392:ex2:words:0:note":"person's name","grammar:392:ex2:words:0:pos":"noun","grammar:392:ex2:words:1:zh":"(topic)","grammar:392:ex2:words:1:pos":"particle","grammar:392:ex2:words:2:zh":"soccer","grammar:392:ex2:words:2:note":"loanword","grammar:392:ex2:words:2:pos":"noun","grammar:392:ex2:words:3:zh":"(object)","grammar:392:ex2:words:3:pos":"particle","grammar:392:ex2:words:4:zh":"to like","grammar:392:ex2:words:4:note":"すき","grammar:392:ex2:words:4:pos":"na-adjective","grammar:392:ex2:words:5:zh":"(polite form)","grammar:392:ex2:words:5:pos":"copula","grammar:392:ex2:points:0":"The object of 「好き」 takes が.","grammar:392:ex2:points:1":"ジャック: a person's name.","grammar:392:ex3:trans":"Jack goes to school every day.","grammar:392:ex3:structure":"〜に通っています","grammar:392:ex3:words:0:zh":"Jack","grammar:392:ex3:words:0:note":"person's name","grammar:392:ex3:words:0:pos":"noun","grammar:392:ex3:words:1:zh":"(topic)","grammar:392:ex3:words:1:pos":"particle","grammar:392:ex3:words:2:zh":"every day","grammar:392:ex3:words:2:note":"まいにち","grammar:392:ex3:words:2:pos":"adverb","grammar:392:ex3:words:3:zh":"school","grammar:392:ex3:words:3:note":"がっこう","grammar:392:ex3:words:3:pos":"noun","grammar:392:ex3:words:4:zh":"(object)","grammar:392:ex3:words:4:pos":"particle","grammar:392:ex3:words:5:zh":"going back and forth","grammar:392:ex3:words:5:note":"かよっています","grammar:392:ex3:words:5:pos":"verb","grammar:392:ex3:points:0":"学校に通う: to go to school.","grammar:392:ex3:points:1":"〜ている: habitual.","grammar:392:ex4:trans":"I'll play with Jack.","grammar:392:ex4:structure":"〜と一緒に遊びます","grammar:392:ex4:words:0:zh":"Jack","grammar:392:ex4:words:0:note":"person's name","grammar:392:ex4:words:0:pos":"noun","grammar:392:ex4:words:1:zh":"with","grammar:392:ex4:words:1:pos":"particle","grammar:392:ex4:words:2:zh":"together","grammar:392:ex4:words:2:note":"いっしょに","grammar:392:ex4:words:2:pos":"adverb","grammar:392:ex4:words:3:zh":"hang out","grammar:392:ex4:words:3:note":"あそびます","grammar:392:ex4:words:3:pos":"verb","grammar:392:ex4:points:0":"〜と一緒に: together with…","grammar:392:ex4:points:1":"遊ぶ→遊びます。","grammar:392:ex5:trans":"Jack is good at cooking.","grammar:392:ex5:structure":"〜は〜が上手です","grammar:392:ex5:words:0:zh":"Jack","grammar:392:ex5:words:0:note":"person's name","grammar:392:ex5:words:0:pos":"noun","grammar:392:ex5:words:1:zh":"(topic)","grammar:392:ex5:words:1:pos":"particle","grammar:392:ex5:words:2:zh":"cooking","grammar:392:ex5:words:2:note":"りょうり","grammar:392:ex5:words:2:pos":"noun","grammar:392:ex5:words:3:zh":"(object)","grammar:392:ex5:words:3:pos":"particle","grammar:392:ex5:words:4:zh":"good at","grammar:392:ex5:words:4:note":"じょうず","grammar:392:ex5:words:4:pos":"na-adjective","grammar:392:ex5:words:5:zh":"(polite form)","grammar:392:ex5:words:5:pos":"copula","grammar:392:ex5:points:0":"The target of 上手 takes が.","grammar:392:ex5:points:1":"料理が上手: good at cooking."},"393":{"example:393:exzh":"I read a book.","example:393:exzh2":"I read the newspaper every day.","example:393:exzh3":"He can read English.","example:393:exzh4":"I read magazines while drinking coffee.","example:393:exzh5":"I'm reading a Japanese novel right now.","grammar:393:ex:trans":"I read a book.","grammar:393:ex:structure":"〜を読みます","grammar:393:ex:explain":"「本を読む」 means 「to read a book」; the object takes 「を」. 「読む（よむ）」 is a godan (u-) verb, and 「読みます」 is its polite form (読む changes to the stem 読み plus ます). In the masu-form it stops at the stem 「読み」, with no sound change. The whole sentence is 「I read a book.」 In plain past it becomes 「読んだ」 (the む sound changes to んだ). This is the most basic pattern of object + を + verb, using the polite form for an everyday action.","grammar:393:ex:words:0:zh":"book","grammar:393:ex:words:0:note":"ほん","grammar:393:ex:words:0:pos":"noun","grammar:393:ex:words:1:zh":"(object marker)","grammar:393:ex:words:1:pos":"particle","grammar:393:ex:words:2:zh":"read","grammar:393:ex:words:2:note":"よみます","grammar:393:ex:words:2:pos":"verb","grammar:393:ex:points:0":"本を読む: to read a book.","grammar:393:ex:points:1":"読む→読みます。","grammar:393:ex2:trans":"I read the newspaper every day.","grammar:393:ex2:structure":"〜を読んでいます","grammar:393:ex2:words:0:zh":"every day","grammar:393:ex2:words:0:note":"まいにち","grammar:393:ex2:words:0:pos":"adverb","grammar:393:ex2:words:1:zh":"newspaper","grammar:393:ex2:words:1:note":"しんぶん","grammar:393:ex2:words:1:pos":"noun","grammar:393:ex2:words:2:zh":"(object marker)","grammar:393:ex2:words:2:pos":"particle","grammar:393:ex2:words:3:zh":"reading","grammar:393:ex2:words:3:note":"よんでいます","grammar:393:ex2:words:3:pos":"verb","grammar:393:ex2:points:0":"新聞: newspaper.","grammar:393:ex2:points:1":"〜ている: habitual (reads every day).","grammar:393:ex3:trans":"He can read English.","grammar:393:ex3:structure":"〜を読めます","grammar:393:ex3:words:0:zh":"he","grammar:393:ex3:words:0:note":"かれ","grammar:393:ex3:words:0:pos":"pronoun","grammar:393:ex3:words:1:zh":"(topic)","grammar:393:ex3:words:1:pos":"particle","grammar:393:ex3:words:2:zh":"English","grammar:393:ex3:words:2:note":"えいご","grammar:393:ex3:words:2:pos":"noun","grammar:393:ex3:words:3:zh":"(object marker)","grammar:393:ex3:words:3:pos":"particle","grammar:393:ex3:words:4:zh":"can read","grammar:393:ex3:words:4:note":"よめます","grammar:393:ex3:words:4:pos":"verb","grammar:393:ex3:points:0":"読める: can read (the potential form of 読む).","grammar:393:ex3:points:1":"英語を読める: to be able to read English.","grammar:393:ex4:trans":"I read magazines while drinking coffee.","grammar:393:ex4:structure":"〜ながら〜ます","grammar:393:ex4:words:0:zh":"magazine","grammar:393:ex4:words:0:note":"ざっし","grammar:393:ex4:words:0:pos":"noun","grammar:393:ex4:words:1:zh":"(object marker)","grammar:393:ex4:words:1:pos":"particle","grammar:393:ex4:words:2:zh":"while reading","grammar:393:ex4:words:2:note":"よみながら","grammar:393:ex4:words:2:pos":"verb","grammar:393:ex4:words:3:zh":"coffee","grammar:393:ex4:words:3:note":"loanword","grammar:393:ex4:words:3:pos":"noun","grammar:393:ex4:words:4:zh":"(object marker)","grammar:393:ex4:words:4:pos":"particle","grammar:393:ex4:words:5:zh":"to drink","grammar:393:ex4:words:5:note":"のみます","grammar:393:ex4:words:5:pos":"verb","grammar:393:ex4:points:0":"❗〜ながら: while doing… (masu-form minus ます + ながら).","grammar:393:ex4:points:1":"読みながら飲む: to drink while reading.","grammar:393:ex5:trans":"I'm reading a Japanese novel.","grammar:393:ex5:structure":"〜を読んでいます","grammar:393:ex5:words:0:zh":"now","grammar:393:ex5:words:0:note":"いま","grammar:393:ex5:words:0:pos":"noun","grammar:393:ex5:words:1:zh":"Japan","grammar:393:ex5:words:1:note":"にほん","grammar:393:ex5:words:1:pos":"noun","grammar:393:ex5:words:2:zh":"'s","grammar:393:ex5:words:2:pos":"particle","grammar:393:ex5:words:3:zh":"novel","grammar:393:ex5:words:3:note":"しょうせつ","grammar:393:ex5:words:3:pos":"noun","grammar:393:ex5:words:4:zh":"(object marker)","grammar:393:ex5:words:4:pos":"particle","grammar:393:ex5:words:5:zh":"reading","grammar:393:ex5:words:5:note":"よんでいます","grammar:393:ex5:words:5:pos":"verb","grammar:393:ex5:points:0":"日本の小説: a Japanese novel.","grammar:393:ex5:points:1":"〜ている: ongoing action.","exam:393:zh":"I'm planning to finish reading the whole novel I borrowed from the library tonight.","exam:393:why":"Reading a novel you borrowed is 「読む」. 「書く」 means to write and can't mean reading a novel that's already written."},"399":{"example:399:exzh":"Grandfather had little book learning, but he was a very smart man.","example:399:exzh2":"He is learned, but he lacks experience.","example:399:exzh3":"It takes time to acquire learning.","example:399:exzh4":"A learned person can explain things clearly without using difficult words.","example:399:exzh5":"Learning is a treasure for life.","grammar:399:ex:trans":"Grandfather had little book learning, but he was a very wise man.","grammar:399:ex:structure":"〜は学はなかったが、〜だった","grammar:399:ex:explain":"「学」 is read がく and, as a standalone noun, means learning or scholarship; the most common patterns are 「学がある」 (to be learned) and 「学がない」 (to have little schooling). To talk about studying in everyday speech, use the verb 「学ぶ（まなぶ）」 or 「勉強する」. This sentence uses 「〜が」 to contrast having no book learning with being very wise, emphasizing that wisdom is not the same as formal education.","grammar:399:ex:words:0:zh":"grandfather","grammar:399:ex:words:0:note":"そふ","grammar:399:ex:words:0:pos":"noun","grammar:399:ex:words:1:zh":"(topic)","grammar:399:ex:words:1:pos":"particle","grammar:399:ex:words:2:zh":"learning","grammar:399:ex:words:2:note":"がく","grammar:399:ex:words:2:pos":"noun","grammar:399:ex:words:3:zh":"(contrast)","grammar:399:ex:words:3:pos":"particle","grammar:399:ex:words:4:zh":"don't have","grammar:399:ex:words:4:pos":"adjective","grammar:399:ex:words:5:zh":"but","grammar:399:ex:words:5:pos":"particle","grammar:399:ex:words:6:zh":"extremely","grammar:399:ex:words:6:pos":"adverb","grammar:399:ex:words:7:zh":"clever","grammar:399:ex:words:7:note":"かしこい","grammar:399:ex:words:7:pos":"adjective","grammar:399:ex:words:8:zh":"person","grammar:399:ex:words:8:note":"ひと","grammar:399:ex:words:8:pos":"noun","grammar:399:ex:words:9:zh":"was (past)","grammar:399:ex:words:9:pos":"copula","grammar:399:ex:points:0":"❗学はなかった: 学 (がく) used on its own means learning or scholarship; the usual patterns are 「学がある／学がない」.","grammar:399:ex:points:1":"〜が: contrastive, although 〜, but … .","grammar:399:ex:points:2":"学は: the second 「は」 marks contrast — as for learning, there is none (but there is wisdom).","grammar:399:ex2:trans":"He is learned, but he lacks experience.","grammar:399:ex2:structure":"〜は＋学はあるが、〜が足りない","grammar:399:ex2:words:0:zh":"he","grammar:399:ex2:words:0:note":"かれ","grammar:399:ex2:words:0:pos":"pronoun","grammar:399:ex2:words:1:zh":"(topic)","grammar:399:ex2:words:1:pos":"particle","grammar:399:ex2:words:2:zh":"learning","grammar:399:ex2:words:2:note":"がく","grammar:399:ex2:words:2:pos":"noun","grammar:399:ex2:words:3:zh":"(contrast)","grammar:399:ex2:words:3:pos":"particle","grammar:399:ex2:words:4:zh":"there is / are","grammar:399:ex2:words:4:pos":"verb","grammar:399:ex2:words:5:zh":"but","grammar:399:ex2:words:5:pos":"particle","grammar:399:ex2:words:6:zh":"experience","grammar:399:ex2:words:6:note":"けいけん","grammar:399:ex2:words:6:pos":"noun","grammar:399:ex2:words:7:zh":"(subject)","grammar:399:ex2:words:7:pos":"particle","grammar:399:ex2:words:8:zh":"not enough","grammar:399:ex2:words:8:note":"たりない; nai-form","grammar:399:ex2:words:8:pos":"verb","grammar:399:ex2:points:0":"「学はある」: 学 used on its own means learning or scholarship; people often say 「学がある／学がない」.","grammar:399:ex2:points:1":"「学は〜、経験が〜」: は sets up a contrast, comparing learning with experience.","grammar:399:ex2:points:2":"「〜が、〜」: the が in the middle means but, linking two opposing ideas.","grammar:399:ex3:trans":"It takes time to acquire learning.","grammar:399:ex3:structure":"〜を身につけるには＋時間がかかる","grammar:399:ex3:words:0:zh":"learning","grammar:399:ex3:words:0:note":"がく","grammar:399:ex3:words:0:pos":"noun","grammar:399:ex3:words:1:zh":"(object)","grammar:399:ex3:words:1:pos":"particle","grammar:399:ex3:words:2:zh":"body","grammar:399:ex3:words:2:note":"み","grammar:399:ex3:words:2:pos":"noun","grammar:399:ex3:words:3:zh":"(onto …)","grammar:399:ex3:words:3:pos":"particle","grammar:399:ex3:words:4:zh":"attach","grammar:399:ex3:words:4:pos":"verb","grammar:399:ex3:words:5:zh":"(purpose)","grammar:399:ex3:words:5:pos":"particle","grammar:399:ex3:words:6:zh":"(topic)","grammar:399:ex3:words:6:pos":"particle","grammar:399:ex3:words:7:zh":"time","grammar:399:ex3:words:7:note":"じかん","grammar:399:ex3:words:7:pos":"noun","grammar:399:ex3:words:8:zh":"(subject)","grammar:399:ex3:words:8:pos":"particle","grammar:399:ex3:words:9:zh":"to take (time)","grammar:399:ex3:words:9:pos":"verb","grammar:399:ex3:points:0":"「学を身につける」: 身につける means to master something, to make it your own; with 学 it means truly acquiring learning.","grammar:399:ex3:points:1":"「〜には」 after a verb's dictionary form means if one is to …, and it is followed by what is required.","grammar:399:ex3:points:2":"「時間がかかる」: the set phrase for taking time; it takes が, not を.","grammar:399:ex4:trans":"A learned person can explain things without using difficult words.","grammar:399:ex4:structure":"学のある人＋は、〜ずに＋動詞できる","grammar:399:ex4:words:0:zh":"learning","grammar:399:ex4:words:0:note":"がく","grammar:399:ex4:words:0:pos":"noun","grammar:399:ex4:words:1:zh":"(subject of the modifying clause)","grammar:399:ex4:words:1:pos":"particle","grammar:399:ex4:words:2:zh":"there is / are","grammar:399:ex4:words:2:pos":"verb","grammar:399:ex4:words:3:zh":"person","grammar:399:ex4:words:3:note":"ひと","grammar:399:ex4:words:3:pos":"noun","grammar:399:ex4:words:4:zh":"(topic)","grammar:399:ex4:words:4:pos":"particle","grammar:399:ex4:words:5:zh":"difficult","grammar:399:ex4:words:5:note":"むずかしい","grammar:399:ex4:words:5:pos":"adjective","grammar:399:ex4:words:6:zh":"word","grammar:399:ex4:words:6:note":"ことば","grammar:399:ex4:words:6:pos":"noun","grammar:399:ex4:words:7:zh":"(object)","grammar:399:ex4:words:7:pos":"particle","grammar:399:ex4:words:8:zh":"use","grammar:399:ex4:words:8:note":"つかわ; nai-form stem","grammar:399:ex4:words:8:pos":"verb","grammar:399:ex4:words:9:zh":"without …","grammar:399:ex4:words:9:pos":"auxiliary verb","grammar:399:ex4:words:10:zh":"explanation","grammar:399:ex4:words:10:note":"せつめい","grammar:399:ex4:words:10:pos":"noun","grammar:399:ex4:words:11:zh":"be able to","grammar:399:ex4:words:11:pos":"verb","grammar:399:ex4:points:0":"「学のある人」: inside a clause that modifies a noun, が often becomes の, so 「学がある人」＝「学のある人」.","grammar:399:ex4:points:1":"「使わずに」: 〜ずに＝〜ないで, meaning without doing … .","grammar:399:ex4:points:2":"「説明できる」: noun + できる means being able to do that thing.","grammar:399:ex5:trans":"Learning is a treasure for life.","grammar:399:ex5:structure":"noun＋は＋noun＋の＋noun＋だ","grammar:399:ex5:words:0:zh":"learning","grammar:399:ex5:words:0:note":"がく","grammar:399:ex5:words:0:pos":"noun","grammar:399:ex5:words:1:zh":"(topic)","grammar:399:ex5:words:1:pos":"particle","grammar:399:ex5:words:2:zh":"whole life","grammar:399:ex5:words:2:note":"いっしょう","grammar:399:ex5:words:2:pos":"noun","grammar:399:ex5:words:3:zh":"'s","grammar:399:ex5:words:3:pos":"particle","grammar:399:ex5:words:4:zh":"treasure","grammar:399:ex5:words:4:note":"たから","grammar:399:ex5:words:4:pos":"noun","grammar:399:ex5:words:5:zh":"(plain-form assertion)","grammar:399:ex5:words:5:pos":"copula","grammar:399:ex5:points:0":"「学は」: 学 used on its own means learning or scholarship, and here it is the topic of the whole sentence.","grammar:399:ex5:points:1":"「一生の宝」: の links two nouns, giving a treasure for one's whole life.","grammar:399:ex5:points:2":"The 「だ」 at the end is the plain-form assertion; for a polite version you can say 「宝です」."}};